def _in_bbox(lat, lon, west, south, east, north) -> bool:
    """Is this position inside the viewport? No bbox means everywhere.

    Handles a viewport that crosses the antimeridian, where west is
    numerically greater than east and a naive `west <= lon <= east`
    silently returns nothing — which looks exactly like "no aircraft
    over the Pacific".
    """
    if west is None or south is None or east is None or north is None:
        return True
    if lat < south or lat > north:
        return False
    if west <= east:
        return west <= lon <= east
    return lon >= west or lon <= east


def _thin_for_viewport(aircraft: list, limit: int) -> list:
    """At most `limit` aircraft, spread across the view.

    WHY NOT JUST THE FIRST N. Taking a slice hands back whatever the
    cache happened to store first, which clusters: five hundred
    aircraft stacked over Frankfurt and an empty Atlantic, on a map
    whose whole job is showing where things are.

    So: anything militarily or otherwise flagged is kept outright, then
    the rest are dealt round-robin out of a coarse grid of cells. The
    result thins dense airspace and keeps the lone aircraft over an
    ocean, which is usually the one worth seeing.
    """
    if len(aircraft) <= limit:
        return aircraft
    keep = [a for a in aircraft if a.get("military") or a.get("interesting")]
    rest = [a for a in aircraft if not (a.get("military") or a.get("interesting"))]
    room = max(0, limit - len(keep))
    if room == 0:
        return keep[:limit]

    cells: dict = {}
    for a in rest:
        # ~2 degree cells: fine enough to separate airports, coarse
        # enough that the round robin actually spreads.
        key = (int(a["lat"] // 2), int(a["lon"] // 2))
        cells.setdefault(key, []).append(a)
    ordered = list(cells.values())
    picked = []
    i = 0
    while len(picked) < room and ordered:
        row = ordered[i % len(ordered)]
        if row:
            picked.append(row.pop())
        else:
            ordered.remove(row)
            continue
        i += 1
    return keep + picked

def _akili_db_path() -> str:
    return f"{DATA_DIR}/akili.db"


@app.get("/api/mining/sequences")
def api_mining_sequences(
    source: str = Query("ucdp"),
    window_days: int = Query(14, ge=1, le=90),
    min_support: int = Query(5, ge=1),
    min_lift: float = Query(1.15, ge=1.0, le=50.0),
    min_consequent: int = Query(20, ge=1),
    limit: int = Query(60, ge=1, le=500),
):
    """What has historically followed what, in the same place.

    Answers "XYZ happened here — what follows?" from this system's own
    recorded history, with the instances attached so an analyst can
    disagree with the count rather than having to trust it.

    Every rule is a correlation over a finite record. Not a cause, and
    not a forecast.
    """
    try:
        import sqlite3
        import sequence_miner as sm
        conn = sqlite3.connect(_akili_db_path())
        try:
            loader = {"ucdp": sm.from_ucdp,
                      "geoconfirmed": sm.from_geoconfirmed}.get(source)
            if not loader:
                return {"available": False, "sources": ["ucdp", "geoconfirmed"],
                        "error": f"unknown source {source!r}", "rules": []}
            out = sm.mine(loader(conn), window_days=window_days,
                          min_support=min_support, min_lift=min_lift,
                          min_consequent=min_consequent)
        finally:
            conn.close()
        return {"available": True, "source": source,
                **{k: v for k, v in out.items() if k != "rules"},
                "rules": out["rules"][:limit]}
    except Exception as e:                                   # noqa: BLE001
        logger.exception("sequence mining failed")
        return {"available": False, "error": str(e)[:200], "rules": []}


@app.get("/api/mining/what-follows")
def api_mining_what_follows(
    kind: str = Query(...),
    source: str = Query("ucdp"),
    window_days: int = Query(14, ge=1, le=90),
):
    """Given something that just happened, what has followed it before."""
    try:
        import sqlite3
        import sequence_miner as sm
        conn = sqlite3.connect(_akili_db_path())
        try:
            loader = {"ucdp": sm.from_ucdp,
                      "geoconfirmed": sm.from_geoconfirmed}.get(source)
            if not loader:
                return {"available": False, "error": f"unknown source {source!r}",
                        "rules": []}
            mined = sm.mine(loader(conn), window_days=window_days)
        finally:
            conn.close()
        return {"available": True, "kind": kind, "source": source,
                "rules": sm.what_follows(mined["rules"], kind),
                "note": mined.get("note")}
    except Exception as e:                                   # noqa: BLE001
        logger.exception("what-follows failed")
        return {"available": False, "error": str(e)[:200], "rules": []}


@app.get("/api/ontology/graph/neighbourhood")
def api_graph_neighbourhood(
    id: str = Query(..., description="node id, e.g. vessel:256843000 or country:UKR"),
    hops: int = Query(2, ge=1, le=3),
    min_conf: float = Query(0.0, ge=0.0, le=1.0),
    limit_per_hop: int = Query(250, ge=10, le=2000),
):
    """A node, its links, AND its links' links.

    This is what the ontology could not do. The old feed returned one
    flat ring of countries, so an analyst could see that a country was
    connected to things but never that those things were connected to
    each other — which is where the finding actually lives.
    """
    try:
        import sqlite3
        import graph_store as gs
        conn = sqlite3.connect(_akili_db_path())
        try:
            gs.ensure_schema(conn)
            return {"available": True,
                    **gs.neighbourhood(conn, id, hops=hops, min_conf=min_conf,
                                       limit_per_hop=limit_per_hop)}
        finally:
            conn.close()
    except Exception as e:                                   # noqa: BLE001
        logger.exception("neighbourhood failed")
        return {"available": False, "error": str(e)[:200], "nodes": [], "links": []}


@app.get("/api/ontology/graph/search")
def api_graph_search(q: str = Query(...), limit: int = Query(20, ge=1, le=100)):
    """Find an entity to start a walk from."""
    try:
        import sqlite3
        import graph_store as gs
        conn = sqlite3.connect(_akili_db_path())
        try:
            gs.ensure_schema(conn)
            return {"available": True, "results": gs.search(conn, q, limit=limit)}
        finally:
            conn.close()
    except Exception as e:                                   # noqa: BLE001
        logger.exception("graph search failed")
        return {"available": False, "error": str(e)[:200], "results": []}


@app.get("/api/forecast/events")
def api_forecast_events(horizon: int = Query(14, ge=1, le=60),
                        limit: int = Query(50, ge=1, le=200),
                        allow_stale: bool = Query(False),
                        backtest: bool = Query(True)):
    """Probability of an event type recurring in a locale, with its score.

    HONEST ABOUT WHAT IT IS. The self-exciting term was fitted, selected
    on held-out time and pooled across all series, and it never beat the
    locale's own base rate — so it is switched off and this is a
    calibrated base-rate forecaster that says so. Measured skill is
    therefore 0.00 against the baseline, which is reported rather than
    hidden, and the reliability curve is genuinely good (the 40-60% band
    is observed at 0.50, the 60-80% at 0.62).

    It also refuses by default: the UCDP copy ends 2026-06-30, so a
    "next 14 days" number from it would be a historical average wearing
    a present tense. Pass allow_stale=true to see them anyway.
    """
    try:
        import sqlite3
        import forecast as _fc
        conn = sqlite3.connect(f"file:{_akili_db_path()}?mode=ro", uri=True)
        try:
            events = _fc.from_ucdp(conn)
            series = _fc.to_series(events)
            models = _fc.fit(series, horizon=horizon)
            out = _fc.forecast(series, models, horizon=horizon, limit=limit,
                               allow_stale=allow_stale)
            out["models"] = len(models)
            out["events"] = len(events)
            if backtest:
                # Shipped WITH the forecast, never on request only: a
                # probability whose skill the reader has to go and look
                # up separately will be read as if it had been checked.
                out["backtest"] = _fc.backtest(series, models, horizon=horizon)
            return out
        finally:
            conn.close()
    except Exception as e:                                   # noqa: BLE001
        logger.exception("forecast failed")
        return {"available": False, "error": str(e)[:200], "forecasts": []}


@app.get("/api/ontology/clusters")
def api_ontology_clusters(min_conf: float = Query(0.0, ge=0.0, le=1.0),
                          link_limit: int = Query(1500, ge=10, le=5000),
                          bridge_limit: int = Query(400, ge=10, le=2000),
                          bridge_types: str = Query("")):
    """The ontology as country plates, their links, and what bridges them.

    Countries are summarised by count and NEVER expanded: the graph is
    overwhelmingly country-anchored — 50,450 `located in` and 30,115
    `flagged in` edges terminate on 243 country nodes — so drawn flat,
    membership wins on volume and the diagram says "country — located in
    — thing" forever. Membership is counted server-side; the links
    between countries and the entities that bridge them are the content.

    The payload stays a few hundred rows however large the graph grows,
    which is the point: it has to be quick and smooth.
    """
    try:
        import sqlite3
        import graph_clusters as gc
        conn = sqlite3.connect(f"file:{_akili_db_path()}?mode=ro", uri=True)
        try:
            types = tuple(t.strip() for t in bridge_types.split(",") if t.strip()) or None
            return gc.overview(conn, min_conf=min_conf, link_limit=link_limit,
                               bridge_limit=bridge_limit, bridge_types=types)
        finally:
            conn.close()
    except Exception as e:                                   # noqa: BLE001
        logger.exception("ontology clusters failed")
        return {"available": False, "error": str(e)[:200],
                "clusters": [], "links": [], "bridges": []}


@app.get("/api/ontology/predict")
def api_ontology_predict(root: str = Query(...),
                         limit: int = Query(25, ge=1, le=100),
                         min_conf: float = Query(0.5, ge=0.0, le=1.0),
                         types: str = Query("")):
    """Links this node probably has that the graph has never stated.

    Every result carries the path that produced it: the reason is the
    deliverable, not the score.
    """
    try:
        import sqlite3
        import link_predict as lp
        conn = sqlite3.connect(f"file:{_akili_db_path()}?mode=ro", uri=True)
        try:
            tset = tuple(t.strip() for t in types.split(",") if t.strip()) or None
            return {"available": True,
                    "predictions": lp.predict(conn, root, limit=limit,
                                              min_conf=min_conf, types=tset)}
        finally:
            conn.close()
    except Exception as e:                                   # noqa: BLE001
        logger.exception("link prediction failed")
        return {"available": False, "error": str(e)[:200], "predictions": []}


@app.get("/api/ontology/findings")
def api_ontology_findings(limit: int = Query(25, ge=1, le=100),
                          min_conf: float = Query(0.05, ge=0.0, le=1.0)):
    """Routes the graph implies — the feed a notification is built from.

    NOTE ON min_conf's DEFAULT, which looks alarmingly low. A CAMEO
    edge's confidence encodes how many reports back it (n/20), not how
    true it is, so a real bilateral agreement covered twice sits at
    0.10. Demanding 0.5 here asked for ten reports of the same
    diplomatic act and silently discarded almost the entire
    cooperation half of the graph.
    """
    try:
        import sqlite3
        import link_predict as lp
        conn = sqlite3.connect(f"file:{_akili_db_path()}?mode=ro", uri=True)
        try:
            found = lp.grouped_chains(conn, limit=limit, min_conf=min_conf)
            return {"available": True, "findings": found,
                    "caveat": "Inferred routes, not observed transfers. "
                              "Each step is a reported relationship and "
                              "should be checked before it is used."}
        finally:
            conn.close()
    except Exception as e:                                   # noqa: BLE001
        logger.exception("ontology findings failed")
        return {"available": False, "error": str(e)[:200], "findings": []}


