@app.get("/adsb")
@_response_cache(expire=30)
def get_adsb(
    lat:   float | None = Query(None),
    lon:   float | None = Query(None),
    dist:  int          = Query(250),
    west:  float | None = Query(None),
    south: float | None = Query(None),
    east:  float | None = Query(None),
    north: float | None = Query(None),
    limit: int          = Query(700),
):
    """Live ADS-B aircraft. Cached 30 s.

    With lat/lon, a disc of `dist` NAUTICAL MILES around that point,
    straight from adsb.lol.

    Without them, the whole world. _global_adsb_cache_loop has been
    polling five regions covering the globe every 60 seconds all along,
    but only anomaly detection could see it — the map asked for a single
    2,000nm disc centred on (20, 10), which is why the sky was busy over
    Europe and Africa and empty everywhere else. adsb.lol also clamps a
    disc that large, so the radius was not doing what it looked like it
    was doing either.
    """
    if lat is None or lon is None:
        now_ts = time.time()
        out = []
        newest = float("inf")
        for ac in list(_GLOBAL_ADSB_CACHE.values()):
            if ac.get("lat") is None or ac.get("lon") is None:
                continue
            # Ten minutes, matching what the poller keeps. Five was
            # shorter than the poller's own retention, so when the
            # upstream rate-limited us the endpoint hid positions the
            # cache still held and the map went blank rather than going
            # stale. Age is reported below instead of being hidden.
            age = now_ts - float(ac.get("last_seen") or 0)
            if age > 600:
                continue
            newest = min(newest, age)
            if not _in_bbox(ac["lat"], ac["lon"], west, south, east, north):
                continue
            out.append({
                "icao":        ac.get("icao") or ac.get("hex") or "",
                "flight":      ac.get("flight") or "",
                "lat":         ac.get("lat"),
                "lon":         ac.get("lon"),
                "alt_baro":    ac.get("alt_baro"),
                "gs":          ac.get("gs"),
                "track":       ac.get("track"),
                "category":    ac.get("category") or "",
                "military":    bool(ac.get("military")),
                "interesting": bool(ac.get("interesting")),
                "type":        ac.get("type") or "",
            })
        total = len(out)
        out = _thin_for_viewport(out, limit)
        print(f"[adsb] viewport → {len(out)} of {total} aircraft")
        newest_s = None if newest == float("inf") else int(newest)
        return {"aircraft": out, "scope": "viewport" if west is not None else "global",
                "available": total, "returned": len(out),
                # So the client can say "positions are 4 minutes old"
                # instead of quietly drawing them as if they were live.
                "newest_fix_seconds": newest_s,
                "stale": bool(newest_s is not None and newest_s > 180),
                "regions": [r["name"] for r in GLOBAL_ADSB_REGIONS]}

    key = f"{round(lat, 2)},{round(lon, 2)},{dist}"
    cached = _adsb_cache.get(key)
    if cached and (time.time() - cached["ts"]) < 30:
        return {"aircraft": cached["data"]}

    url = f"https://api.adsb.lol/v2/lat/{lat}/lon/{lon}/dist/{dist}"
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Akili/1.0"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            raw = _json.loads(resp.read())
    except Exception as e:
        logger.exception("get_adsb: adsb.lol fetch failed")
        print(f"[adsb] fetch error: {e}")
        return {"aircraft": []}

    sample = raw.get("ac", [{}])[0] if raw.get("ac") else {}
    print(f"[adsb] raw keys={list(raw.keys())} total={raw.get('total','?')} sample_fields={list(sample.keys())[:12]}")

    aircraft = []
    for ac in raw.get("ac", []):
        lat_ac = ac.get("lat")
        lon_ac = ac.get("lon")
        if lat_ac is None or lon_ac is None:
            continue
        db_flags = int(ac.get("dbFlags") or 0)
        aircraft.append({
            "icao":        (ac.get("hex") or "").upper(),
            "flight":      (ac.get("flight") or "").strip(),
            "lat":         lat_ac,
            "lon":         lon_ac,
            "alt_baro":    ac.get("alt_baro"),
            "gs":          ac.get("gs"),
            "track":       ac.get("track"),
            "category":    ac.get("category") or "",
            "military":    bool(db_flags & 1),
            "interesting": bool(db_flags & 2),
            "type":        ac.get("t") or "",
        })

    print(f"[adsb] lat={lat:.2f} lon={lon:.2f} dist={dist}nm → {len(aircraft)} aircraft")
    now_ts = time.time()
    _adsb_cache[key] = {"ts": now_ts, "data": aircraft}
    # Populate global cache from viewport results too
    for ac in aircraft:
        _GLOBAL_ADSB_CACHE[ac["icao"]] = {**ac, "hex": ac["icao"], "last_seen": now_ts}
    # Record to history (throttled — only new records, once per aircraft per minute)
    try:
        _record_adsb_history(aircraft)
    except Exception:
        pass
    return {"aircraft": aircraft}


