# SYSTEM 4 — Passive Anomaly Detection
# ══════════════════════════════════════════════════════════════════════════════

_ANOMALY_CHOKEPOINTS = {
    "Strait of Hormuz":   {"center_lat": 26.5,  "center_lon": 56.4},
    "Bab el-Mandeb":      {"center_lat": 12.6,  "center_lon": 43.4},
    "Suez Canal":         {"center_lat": 30.5,  "center_lon": 32.4},
    "Strait of Malacca":  {"center_lat": 3.0,   "center_lon": 103.5},
    "Taiwan Strait":      {"center_lat": 23.5,  "center_lon": 120.2},
    "Strait of Gibraltar":{"center_lat": 35.9,  "center_lon": -5.6},
}

_MIL_CALLSIGN_PREFIXES = [
    'RCH', 'DUKE', 'EVAC', 'RRR', 'TOPCAT', 'RAGE', 'DARK', 'VIPER',
    'HAVOC', 'CNV', 'NAVY', 'VENUS', 'REACH', 'PAT', 'GOLD', 'SKULL',
]


def _haversine(lat1, lon1, lat2, lon2):
    R = 6371
    dlat = math.radians(lat2 - lat1)
    dlon = math.radians(lon2 - lon1)
    a = math.sin(dlat / 2) ** 2 + math.cos(math.radians(lat1)) * math.cos(math.radians(lat2)) * math.sin(dlon / 2) ** 2
    return R * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))


def _haversine_m(lat1, lon1, lat2, lon2) -> float:
    """Distance in metres between two lat/lon points."""
    return _haversine(lat1, lon1, lat2, lon2) * 1000.0


def _distance_to_nearest_port_km(lat, lon) -> float:
    """Returns km distance to nearest PortBoundary (pre-filtered within 0.5°)."""
    try:
        from database import PortBoundary as _PB, get_db as _gdb
        deg_r = 0.5
        with _gdb() as _db:
            ports = _db.query(_PB).filter(
                _PB.latitude.between(lat - deg_r, lat + deg_r),
                _PB.longitude.between(lon - deg_r, lon + deg_r),
            ).all()
        if not ports:
            return 999.0
        dists = [
            _haversine(lat, lon, p.latitude, p.longitude)
            for p in ports if p.latitude and p.longitude
        ]
        return min(dists) if dists else 999.0
    except Exception:
        return 999.0


def _nearest_port_region_id(lat, lon, deg_r: float = 0.5):
    """Best-effort lat/lon -> region_id, via nearest PortBoundary within a
    small bounding box (same bbox-prefilter pattern as
    _distance_to_nearest_port_km above). Returns None if no port with a
    known region_id is found nearby — callers must treat None as "region
    unknown", never as an implicit match for any specific region scope.

    Used by DarkShipDetector's region_fn — only invoked when a real,
    non-"ALL" AIS_DARK_SHIP rule scope actually needs it (see
    _run_dark_ship_rules / _forge_detection_cycle), since this runs one DB
    query per vessel and the seeded/real production rule never needs it."""
    try:
        from database import PortBoundary as _PB2, get_db as _gdb2
        with _gdb2() as _db2:
            ports = _db2.query(_PB2).filter(
                _PB2.latitude.between(lat - deg_r, lat + deg_r),
                _PB2.longitude.between(lon - deg_r, lon + deg_r),
                _PB2.region_id.isnot(None),
            ).all()
        if not ports:
            return None
        best = min(ports, key=lambda p: _haversine(lat, lon, p.latitude, p.longitude))
        return best.region_id
    except Exception:
        return None


def _is_military_callsign(callsign):
    cs = (callsign or '').strip().upper()
    return any(cs.startswith(p) for p in _MIL_CALLSIGN_PREFIXES)


def _cluster_by_location(markers, radius_km=100):
    clusters = []
    used = set()
    for i, m in enumerate(markers):
        if i in used:
            continue
        cluster = [m]
        used.add(i)
        for j, m2 in enumerate(markers):
            if j in used:
                continue
            if _haversine(m.get('lat', 0), m.get('lon', 0), m2.get('lat', 0), m2.get('lon', 0)) < radius_km:
                cluster.append(m2)
                used.add(j)
        clusters.append(cluster)
    return clusters


def _cluster_center(cluster):
    lats = [m.get('lat', 0) for m in cluster if m.get('lat')]
    lons = [m.get('lon', 0) for m in cluster if m.get('lon')]
    if not lats:
        return (0, 0)
    return (sum(lats) / len(lats), sum(lons) / len(lons))


async def _findings_warm_loop():
    """Keep the inferred-link cache warm, off the event loop.

    WHY A WARMER AND NOT JUST A CACHE. grouped_chains() walks the whole
    edge table. Measured through the running server on a cold page
    cache it took 50 seconds the first time, and the notification feed
    polls it — so the first client after every restart paid that, and so
    did anyone who opened the findings panel before them. A cache that
    is only ever filled by a user request means some user always pays
    for it.

    Recomputed a little faster than the cache expires, so a request
    should never find it cold. In an executor, never inline: this is
    exactly the shape of blocking work that had a trivial query queued
    behind it for fifteen seconds earlier tonight.
    """
    # OFF UNLESS ASKED FOR. This holds a ~59MB adjacency for the whole
    # graph, and on a memory-constrained container that is the
    # difference between a process that runs and one the platform kills
    # — which reaches a browser as a 502 with no CORS headers, looking
    # for all the world like a CORS misconfiguration. The endpoint works
    # without the warmer; it is only slower on the first call. Enable
    # with HW_WARM_FINDINGS=1 once there is known memory headroom.
    if (os.getenv("HW_WARM_FINDINGS") or "").strip() not in ("1", "true", "yes"):
        print("[ontology] findings cache warmer disabled "
              "(set HW_WARM_FINDINGS=1 to enable)")
        return

    await asyncio.sleep(120)
    while True:
        try:
            import sqlite3 as _sq
            import link_predict as _lp
            loop_ = asyncio.get_event_loop()

            def _warm():
                conn = _sq.connect(f"file:{_akili_db_path()}?mode=ro", uri=True)
                try:
                    t0 = time.monotonic()
                    found = _lp.grouped_chains(conn, limit=25)
                    return len(found), time.monotonic() - t0
                finally:
                    conn.close()

            n, secs = await loop_.run_in_executor(_executor, _warm)
            print(f"[ontology] findings cache warmed: {n} routes in {secs:.1f}s")
        except Exception as e:                               # noqa: BLE001
            # A warmer that takes the process down is worse than a cold
            # cache, and the endpoint still works either way.
            print(f"[ontology] findings warm failed: {e}")
        # Just under link_predict.CACHE_TTL_S so the cache never lapses.
        await asyncio.sleep(780)


async def _vessel_resolution_loop():
    """Keep the sanctions bridge current.

    Every vessel we have ever tracked, matched against the sanctions
    store. The whole fleet takes about 17 seconds, so the interval is
    set by how often the inputs change — new AIS names arrive
    continuously, new sanctions listings daily — not by cost.
    """
    await asyncio.sleep(90)
    while True:
        if HEAVY_FEEDS_PAUSED:
            await asyncio.sleep(3600)
            continue
        try:
            import ftm_resolve
            loop_ = asyncio.get_event_loop()
            stats = await loop_.run_in_executor(
                _executor, lambda: ftm_resolve.resolve_all(_akili_db_path()))
            print(f"[ontology] vessel resolution: examined {stats.get('examined')}, "
                  f"linked {stats.get('linked')}, for review {stats.get('for_review')}")
        except Exception as e:                               # noqa: BLE001
            print(f"[ontology] vessel resolution failed: {e}")
        await asyncio.sleep(6 * 3600)


async def _global_adsb_cache_loop():
    """Poll ADS-B globally every 60s to populate _GLOBAL_ADSB_CACHE for anomaly detection."""
    global _GLOBAL_ADSB_CACHE
    await asyncio.sleep(30)
    while True:
        if HEAVY_FEEDS_PAUSED:
            await asyncio.sleep(60)
            continue
        try:
            loop = asyncio.get_event_loop()
            fetched_total = 0
            for region in GLOBAL_ADSB_REGIONS:
                url = f"https://api.adsb.lol/v2/lat/{region['lat']}/lon/{region['lon']}/dist/{region['dist']}"
                def _fetch(u=url):
                    try:
                        import urllib.request as _ur
                        req = _ur.Request(u, headers={"User-Agent": "Akili/1.0"})
                        with _ur.urlopen(req, timeout=15) as r:
                            return _json.loads(r.read()).get("ac", [])
                    except Exception as e:
                        logger.exception("adsb background poll: region fetch failed")
                        return []
                aircraft_raw = await loop.run_in_executor(_executor, _fetch)
                fetched_total += len(aircraft_raw)
                now_ts = time.time()
                for ac in aircraft_raw:
                    hex_id = (ac.get("hex") or "").upper()
                    if not hex_id:
                        continue
                    db_flags = int(ac.get("dbFlags") or 0)
                    _GLOBAL_ADSB_CACHE[hex_id] = {
                        "hex":        hex_id,
                        "icao":       hex_id,
                        "flight":     (ac.get("flight") or "").strip(),
                        "lat":        ac.get("lat"),
                        "lon":        ac.get("lon"),
                        "alt_baro":   ac.get("alt_baro"),
                        "gs":         ac.get("gs"),
                        "track":      ac.get("track"),
                        "category":   ac.get("category") or "",
                        "military":   bool(db_flags & 1),
                        "interesting":bool(db_flags & 2),
                        "type":       ac.get("t") or "",
                        "last_seen":  now_ts,
                    }
                # Record to history
                mapped = [{"icao": (ac.get("hex") or "").upper(), "flight": (ac.get("flight") or "").strip(),
                            "lat": ac.get("lat"), "lon": ac.get("lon"), "alt_baro": ac.get("alt_baro"),
                            "gs": ac.get("gs"), "track": ac.get("track"), "category": ac.get("category") or "",
                            "military": bool(int(ac.get("dbFlags") or 0) & 1), "type": ac.get("t") or ""}
                           for ac in aircraft_raw if ac.get("lat") is not None]
                try:
                    _record_adsb_history(mapped)
                except Exception:
                    pass
                # adsb.lol is free and rate-limited, and these are
                # 3,000nm queries. Ten of them two seconds apart earned a
                # 429 across the board; six seconds apart does not.
                await asyncio.sleep(6)
            # A CYCLE THAT FETCHED NOTHING IS A FAILURE, NOT AN EMPTY SKY.
            # adsb.lol rate-limits, and when every region comes back 429
            # the pruning below used to delete the entire cache — the map
            # went from 11,808 aircraft to 0 with nothing on screen to say
            # why, and only a swallowed traceback in the log. Keeping the
            # last known positions is both more useful and more honest:
            # they are real observations that are getting old, which the
            # endpoint already reports through last_seen.
            if fetched_total == 0:
                print(f"[ADSB-GLOBAL] all {len(GLOBAL_ADSB_REGIONS)} regions returned "
                      f"nothing — keeping {len(_GLOBAL_ADSB_CACHE)} known positions")
                await asyncio.sleep(180)
                continue

            # Prune entries older than 10 minutes
            cutoff = time.time() - 600
            stale = [k for k, v in list(_GLOBAL_ADSB_CACHE.items()) if v.get("last_seen", 0) < cutoff]
            for k in stale:
                _GLOBAL_ADSB_CACHE.pop(k, None)
            # Hard cap at 3000 entries — drop oldest 500 if exceeded
            if len(_GLOBAL_ADSB_CACHE) > 12000:
                _oldest = sorted(_GLOBAL_ADSB_CACHE.items(), key=lambda x: x[1].get("last_seen", 0))
                for k, _ in _oldest[:500]:
                    _GLOBAL_ADSB_CACHE.pop(k, None)
            print(f"[ADSB-GLOBAL] {len(_GLOBAL_ADSB_CACHE)} aircraft tracked globally")
        except Exception as e:
            print(f"[ADSB-GLOBAL] loop error: {e}")
        await asyncio.sleep(120)


def _cross_domain_correlation(now_iso: str) -> list:
    """Check for military vessels/aircraft near recent high-severity news events.

    NOTE: this is no longer called from any live code path — its only caller,
    _anomaly_detection_loop(), was deleted as dead code (disabled background task,
    see git history). It is kept here because test_null_island_correlation.py has a
    dedicated regression test directly exercising this function's Null-Island
    fabricated-position guard (vessel/aircraft with no reported lat/lon must never be
    treated as being at (0, 0)). Do not delete without also removing/updating that test.
    """
    results = []
    cutoff_iso = (datetime.utcnow() - timedelta(hours=2)).isoformat()
    recent_news = [
        m for m in _NEWS_CONFLICT_MARKERS
        if isinstance(m, dict)
        and m.get('timestamp', '') > cutoff_iso
        and m.get('severity') in ('critical', 'significant')
        and m.get('lat') and m.get('lon')
    ]
    for news in recent_news[:10]:
        nlat = news.get('lat', 0)
        nlon = news.get('lon', 0)
        nearby_vessels = []
        with _AIS_LOCK:
            for mmsi, vessel in _AIS_VESSELS.items():
                # A vessel can land in _AIS_VESSELS from a ShipStaticData
                # message alone, before any PositionReport ever arrives —
                # it then has no "lat"/"lon" key at all. `or 0` would silently
                # turn that into Null Island (0, 0) and let it "correlate"
                # with any news event that happens to be near there. Require
                # a real reported position before treating it as nearby.
                if not (vessel.get('lat') and vessel.get('lon')):
                    continue
                if vessel.get('ship_type', 0) in range(35, 40):
                    d = _haversine(nlat, nlon, vessel['lat'], vessel['lon'])
                    if d < 100:
                        nearby_vessels.append({"mmsi": mmsi, "name": vessel.get('name', 'Unknown'), "distance_km": round(d, 1)})
        nearby_ac = []
        for ac in list(_GLOBAL_ADSB_CACHE.values()):
            # Same fabricated-position hazard as above: an ADS-B cache entry
            # can have lat/lon set to None (feed row with no position yet).
            if not (ac.get('lat') and ac.get('lon')):
                continue
            if ac.get('military') or _is_military_callsign(ac.get('flight', '')):
                d = _haversine(nlat, nlon, ac['lat'], ac['lon'])
                if d < 200:
                    nearby_ac.append({"callsign": (ac.get('flight') or '').strip() or ac.get('hex', ''), "icao24": ac.get('hex', ''), "distance_km": round(d, 1)})
        if nearby_vessels or nearby_ac:
            results.append({
                "id": str(uuid.uuid4()),
                "type": "cross_domain_correlation",
                "severity": "significant",
                "title": f"Military activity near: {(news.get('title') or '')[:60]}",
                "subtitle": f"{len(nearby_vessels)} military vessel(s), {len(nearby_ac)} military aircraft nearby",
                "description": (
                    f"A {news.get('severity', '')} security event was reported near ({nlat:.2f}, {nlon:.2f}). "
                    f"{len(nearby_vessels)} military vessel(s) and {len(nearby_ac)} military aircraft are within proximity."
                ),
                "reason": f"News severity '{news.get('severity','')}' + {len(nearby_vessels)} military vessels <100km + {len(nearby_ac)} military aircraft <200km",
                "lat": nlat, "lon": nlon,
                "timestamp": now_iso,
                "entity": news.get('url', '') or f"news_{int(nlat*10)}_{int(nlon*10)}",
                "entity_name": (news.get('title') or '')[:80],
                "entity_type": "correlation",
                "correlated_data": {
                    "news": {"title": news.get('title'), "source": news.get('source'), "severity": news.get('severity')},
                    "vessels": nearby_vessels[:5],
                    "aircraft": nearby_ac[:5],
                },
                "classification": None,
                "pinned": False,
                "dismissed": False,
            })
    return results


def _calculate_overall_threat_level(alerts):
    if any(a.get('severity') == 'critical' for a in alerts):
        return 'critical'
    if sum(1 for a in alerts if a.get('severity') == 'significant') >= 3:
        return 'significant'
    if len(alerts) >= 5:
        return 'elevated'
    return 'normal'


@app.get("/api/alerts/recent")
async def get_recent_alerts(
    rule_name: str = Query(None, description="Filter by rule_name"),
    hours: int = Query(6, description="Lookback window in hours"),
    user=None,
):
    # Sourced entirely from _forge_alerts (real AIS/ADSB/NEWS/loitering alerts).
    # This previously also checked _ANOMALY_ALERTS, a buffer only ever populated by
    # _anomaly_detection_loop() — a background task that has been disabled
    # (commented out) since before this round, so that buffer was always empty.
    # Removed along with the dead loop; this endpoint now serves only real data.
    cutoff = (datetime.utcnow() - timedelta(hours=hours)).isoformat()
    recent = [a for a in _forge_alerts if a.get('timestamp', '') > cutoff and not a.get('dismissed')]
    if rule_name:
        recent = [a for a in recent if a.get('rule_name') == rule_name or a.get('rule_trigger') == rule_name]
    return {
        "count": len(recent),
        "alerts": recent[-50:],
        "threat_level": _calculate_overall_threat_level(recent),
    }


@app.post("/api/alerts/{alert_id}/classify")
async def classify_alert(alert_id: str, request: Request, user=None):
    body = await request.json()
    classification = body.get("classification")
    for alert in _forge_alerts:
        if alert.get("id") == alert_id:
            alert["classification"] = classification
            alert["classified_by"] = getattr(user, "email", "anonymous") if user else "anonymous"
            alert["classified_at"] = datetime.utcnow().isoformat()
            if classification == "dismiss":
                alert["dismissed"] = True
            return {"status": "ok", "alert": alert}
    return JSONResponse({"error": "Alert not found"}, status_code=404)


@app.post("/api/alerts/{alert_id}/pin")
async def pin_alert(alert_id: str, user=None):
    for alert in _forge_alerts:
        if alert.get("id") == alert_id:
            alert["pinned"] = not alert.get("pinned", False)
            return {"status": "ok", "pinned": alert["pinned"]}
    return JSONResponse({"error": "Alert not found"}, status_code=404)


# Real human-workflow state for the mobile companion's Alerts tab (and any
# future console use) — unlike classify_alert()/pin_alert() above (in-memory
# only, lost on restart), these persist to the real Alert DB row's own
# status/acknowledged_at/acknowledged_by columns (database.py's Alert model
# already had them, unused by any endpoint until now) as well as updating
# the in-memory _forge_alerts copy every GET already reads from, so the
# change is both durable and immediately visible without a restart.
@app.post("/api/alerts/{alert_id}/acknowledge")
async def acknowledge_alert(alert_id: str, request: Request):
    from database import Alert as _AlertRow, get_db as _gdb_ack
    body = {}
    try:
        body = await request.json()
    except Exception:
        pass
    by = (body or {}).get("by") or "operator"
    now = datetime.utcnow()
    # Real finding, live: _forge_alerts (the in-memory list every GET reads)
    # is the authoritative "does this alert exist right now" — confirmed
    # live that a real, currently-active alert can have no backing Alert DB
    # row at all (not every detection path persists one). Requiring a DB row
    # first would 404 on real, valid alerts, so the in-memory list is
    # checked first; the DB row is updated too when one exists, best-effort,
    # never blocking on its absence.
    in_memory_hit = None
    for alert in _forge_alerts:
        if alert.get("id") == alert_id:
            alert["status"] = "acknowledged"
            alert["acknowledged_at"] = now.isoformat()
            alert["acknowledged_by"] = by
            in_memory_hit = alert
            break
    with _gdb_ack() as db:
        row = db.query(_AlertRow).filter(_AlertRow.alert_id == alert_id).first()
        if row:
            row.status = "acknowledged"
            row.acknowledged_at = now
            row.acknowledged_by = by
            db.commit()
    if not in_memory_hit and not row:
        return JSONResponse({"error": "Alert not found"}, status_code=404)
    return {"status": "ok", "acknowledged_at": now.isoformat(), "acknowledged_by": by}


@app.post("/api/alerts/{alert_id}/escalate")
async def escalate_alert(alert_id: str, request: Request):
    """Real escalation flag — reuses the Alert row's own real `tags` JSON
    column (already there for exactly this kind of analyst-set label)
    rather than a new schema column for a single boolean."""
    from database import Alert as _AlertRow, get_db as _gdb_esc
    body = {}
    try:
        body = await request.json()
    except Exception:
        pass
    by = (body or {}).get("by") or "operator"
    # Same real fix as acknowledge_alert() above — _forge_alerts is checked
    # first since not every real, currently-active alert has a backing
    # Alert DB row.
    in_memory_hit = None
    for alert in _forge_alerts:
        if alert.get("id") == alert_id:
            tags = alert.get("tags") or []
            if "escalated" not in tags:
                tags.append("escalated")
            alert["tags"] = tags
            alert["escalated_by"] = by
            in_memory_hit = alert
            break
    with _gdb_esc() as db:
        row = db.query(_AlertRow).filter(_AlertRow.alert_id == alert_id).first()
        if row:
            tags = json.loads(row.tags or "[]")
            if "escalated" not in tags:
                tags.append("escalated")
            row.tags = json.dumps(tags)
            db.commit()
    if not in_memory_hit and not row:
        return JSONResponse({"error": "Alert not found"}, status_code=404)
    return {"status": "ok", "escalated": True}


