async def _generate_weekly_snapshot():
    """Gather stats from history tables and ask Claude to produce a narrative summary."""
    try:
        from database import AircraftHistory, VesselHistory, WeeklySnapshot, get_db
    except ImportError:
        print("[weekly] database models not available")
        return

    week_end   = datetime.utcnow()
    week_start = week_end - timedelta(days=7)
    print(f"[weekly] generating snapshot {week_start.date()} → {week_end.date()}")

    with get_db() as db:
        vessel_count = db.query(VesselHistory).filter(
            VesselHistory.timestamp.between(week_start, week_end)
        ).count()

        chokepoint_traffic = {}
        for cp_name, cp_data in _ANOMALY_CHOKEPOINTS.items():
            cp_lat, cp_lon = cp_data['center_lat'], cp_data['center_lon']
            lat_r = 50 / 111.0
            lon_r = 50 / (111.0 * max(0.1, abs(math.cos(math.radians(cp_lat)))))
            count = db.query(VesselHistory).filter(
                VesselHistory.timestamp.between(week_start, week_end),
                VesselHistory.lat.between(cp_lat - lat_r, cp_lat + lat_r),
                VesselHistory.lon.between(cp_lon - lon_r, cp_lon + lon_r),
            ).count()
            chokepoint_traffic[cp_name] = count

        aircraft_count = db.query(AircraftHistory).filter(
            AircraftHistory.timestamp.between(week_start, week_end)
        ).count()
        military_count = db.query(AircraftHistory).filter(
            AircraftHistory.timestamp.between(week_start, week_end),
            AircraftHistory.is_military == True,
        ).count()

    news_by_region = {}
    news_by_severity = {"critical": 0, "significant": 0, "elevated": 0, "low": 0}
    for marker in _NEWS_CONFLICT_MARKERS:
        region = marker.get('region', 'unknown')
        news_by_region[region] = news_by_region.get(region, 0) + 1
        sev = marker.get('severity', 'low')
        if sev in news_by_severity:
            news_by_severity[sev] += 1

    # Was _ANOMALY_ALERTS (a buffer only populated by the now-deleted, long-disabled
    # _anomaly_detection_loop() — always empty). Use the real _forge_alerts buffer,
    # grouped by rule_name (its closest analog to a "type").
    alert_by_type = {}
    for alert in _forge_alerts:
        atype = alert.get('rule_name') or alert.get('type') or 'unknown'
        alert_by_type[atype] = alert_by_type.get(atype, 0) + 1

    maritime_stats = {
        "total_vessel_positions": vessel_count,
        "avg_daily_positions": vessel_count // 7,
        "chokepoint_traffic": chokepoint_traffic,
    }
    aviation_stats = {
        "total_aircraft_positions": aircraft_count,
        "military_positions": military_count,
        "military_ratio": round(military_count / max(aircraft_count, 1) * 100, 1),
    }
    news_stats = {
        "by_region": news_by_region,
        "by_severity": news_by_severity,
        "total": sum(news_by_region.values()),
    }

    stats_text = _json.dumps({
        "maritime": maritime_stats,
        "aviation": aviation_stats,
        "news": news_stats,
        "alerts": alert_by_type,
    }, indent=2)

    summary = stats_text   # fallback if Claude unavailable
    threat_assessment = '{}'
    trends = '{}'

    api_key = os.getenv("ANTHROPIC_API_KEY")
    if api_key:
        try:
            import anthropic as _anthropic
            def _call_claude():
                client = _anthropic.Anthropic(api_key=api_key)
                resp = client.messages.create(
                    model="claude-haiku-4-5-20251001",
                    max_tokens=1500,
                    system=(
                        "You are a weekly intelligence analyst for Parallax. "
                        "Produce a structured JSON analysis. Include: "
                        "'summary' (3-paragraph narrative), "
                        "'threat_levels' (dict: region → green/amber/red), "
                        "'trends' (dict: topic → increasing/stable/decreasing). "
                        "Respond with JSON only."
                    ),
                    messages=[{"role": "user", "content": f"Weekly stats {week_start.date()} to {week_end.date()}:\n\n{stats_text}"}],
                )
                return resp.content[0].text
            loop = asyncio.get_event_loop()
            analysis = await loop.run_in_executor(_executor, _call_claude)
            try:
                parsed = _json.loads(analysis)
                summary = parsed.get('summary', analysis)
                threat_assessment = _json.dumps(parsed.get('threat_levels', {}))
                trends = _json.dumps(parsed.get('trends', {}))
            except Exception:
                summary = analysis
        except Exception as e:
            print(f"[weekly] Claude analysis failed: {e}")

    snapshot = WeeklySnapshot(
        week_start=week_start,
        week_end=week_end,
        maritime_stats=_json.dumps(maritime_stats),
        aviation_stats=_json.dumps(aviation_stats),
        news_stats=_json.dumps(news_stats),
        alert_stats=_json.dumps(alert_by_type),
        summary=summary,
        threat_assessment=threat_assessment,
        trends=trends,
    )
    try:
        from database import get_db
        with get_db() as db:
            db.add(snapshot)
            db.commit()
        print(f"[weekly] snapshot saved for {week_start.date()}")
    except Exception as e:
        print(f"[weekly] save error: {e}")


async def _weekly_snapshot_loop():
    """Wait until next Sunday midnight UTC, then generate weekly snapshot."""
    while True:
        now = datetime.utcnow()
        days_until_sunday = (6 - now.weekday()) % 7
        if days_until_sunday == 0 and now.hour >= 1:
            days_until_sunday = 7
        next_sunday = now.replace(hour=0, minute=0, second=0, microsecond=0) + timedelta(days=days_until_sunday)
        wait_seconds = (next_sunday - now).total_seconds()
        print(f"[weekly] next snapshot in {wait_seconds / 3600:.1f} hours")
        await asyncio.sleep(wait_seconds)
        try:
            await _generate_weekly_snapshot()
        except Exception as e:
            print(f"[weekly] generation failed: {e}")


@app.get("/api/statistics/weekly")
def get_weekly_snapshots(weeks: int = Query(12), user=None):
    try:
        from database import WeeklySnapshot, get_db
    except ImportError as e:
        logger.exception("statistics/weekly: import/query failed")
        return {"count": 0, "snapshots": []}
    with get_db() as db:
        snapshots = db.query(WeeklySnapshot).order_by(WeeklySnapshot.week_start.desc()).limit(weeks).all()
    return {
        "count": len(snapshots),
        "snapshots": [
            {
                "week_start": s.week_start.isoformat(),
                "week_end":   s.week_end.isoformat(),
                "maritime":   _json.loads(s.maritime_stats or '{}'),
                "aviation":   _json.loads(s.aviation_stats or '{}'),
                "news":       _json.loads(s.news_stats or '{}'),
                "alerts":     _json.loads(s.alert_stats or '{}'),
                "summary":    s.summary or '',
                "threat_assessment": _json.loads(s.threat_assessment or '{}'),
                "trends":     _json.loads(s.trends or '{}'),
            }
            for s in snapshots
        ],
    }


# ── Overwatch: satellite imagery object detection (ONNX — no torch/CUDA) ──────

# Cores ONNX inference may use. Deliberately NOT all of them: the event loop
# runs on the main thread and needs one, and the health endpoint has to stay
# answerable while a scan runs. Two cores held back was the smallest reserve
# that kept probes responsive in testing.
_IMAGERY_ONNX_THREADS = max(1, int(os.getenv("IMAGERY_ONNX_THREADS", "0"))
                            or max(1, (os.cpu_count() or 4) - 2))
_IMAGERY_TILE_FETCHERS = max(2, int(os.getenv("IMAGERY_TILE_FETCHERS", "6")))

# Largest stitched image an Esri scan may build, in pixels. Held well under
# PIL's 179MP decompression-bomb ceiling: a stitch near that limit is ~1.8GB
# of RGB and stalls the process through memory pressure alone, whatever
# thread it runs on.
_IMAGERY_MAX_STITCH_PX = max(1_000_000, int(os.getenv("IMAGERY_MAX_STITCH_PX", str(80_000_000))))

_OW_DOTA_CLASSES = [
    "plane","ship","storage-tank","baseball-diamond","tennis-court",
    "basketball-court","ground-track-field","harbor","bridge",
    "large-vehicle","small-vehicle","helicopter","roundabout",
    "soccer-ball-field","swimming-pool",
]
# DOTA v2 extends with container-crane, airport, helipad (indices 15-17).
# yolov8m-obb is the medium-size model trained on DOTAv1 (same 15 classes,
# better accuracy). "dota-v2" key loads yolov8m-obb and falls back to nano.
_OW_DOTA_V2_CLASSES = _OW_DOTA_CLASSES + ["container-crane", "airport", "helipad"]
_OW_COCO_CLASSES = [
    "person","bicycle","car","motorcycle","airplane","bus","train","truck","boat",
    "traffic light","fire hydrant","stop sign","parking meter","bench","bird","cat",
    "dog","horse","sheep","cow","elephant","bear","zebra","giraffe","backpack",
    "umbrella","handbag","tie","suitcase","frisbee","skis","snowboard","sports ball",
    "kite","baseball bat","baseball glove","skateboard","surfboard","tennis racket",
    "bottle","wine glass","cup","fork","knife","spoon","bowl","banana","apple",
    "sandwich","orange","broccoli","carrot","hot dog","pizza","donut","cake","chair",
    "couch","potted plant","bed","dining table","toilet","tv","laptop","mouse",
    "remote","keyboard","cell phone","microwave","oven","toaster","sink",
    "refrigerator","book","clock","vase","scissors","teddy bear","hair drier","toothbrush",
]

# Category / subcategory taxonomy for detections (frontend mirrors this)
_OW_CATEGORY_MAP = {
    "plane":              ("Aircraft",       "Fixed-Wing"),
    "airplane":           ("Aircraft",       "Fixed-Wing"),
    "helicopter":         ("Aircraft",       "Rotary-Wing"),
    "ship":               ("Vessel",         "Large Ship"),
    "boat":               ("Vessel",         "Small Vessel"),
    "harbor":             ("Infrastructure", "Port/Harbor"),
    "bridge":             ("Infrastructure", "Bridge"),
    "train":              ("Infrastructure", "Rail"),
    "large-vehicle":      ("Vehicle",        "Heavy Vehicle"),
    "large vehicle":      ("Vehicle",        "Heavy Vehicle"),
    "truck":              ("Vehicle",        "Heavy Vehicle"),
    "bus":                ("Vehicle",        "Heavy Vehicle"),
    "small-vehicle":      ("Vehicle",        "Light Vehicle"),
    "small vehicle":      ("Vehicle",        "Light Vehicle"),
    "car":                ("Vehicle",        "Light Vehicle"),
    "motorcycle":         ("Vehicle",        "Motorcycle"),
    "storage-tank":       ("Structure",      "Storage Tank"),
    "storage tank":       ("Structure",      "Storage Tank"),
    "roundabout":         ("Structure",      "Road Feature"),
    "baseball-diamond":   ("Facility",       "Sports"),
    "tennis-court":       ("Facility",       "Sports"),
    "basketball-court":   ("Facility",       "Sports"),
    "ground-track-field": ("Facility",       "Sports"),
    "soccer-ball-field":  ("Facility",       "Sports"),
    "swimming-pool":      ("Facility",       "Recreational"),
    # DOTA v2 additions
    "container-crane":    ("Infrastructure", "Container Crane"),
    "airport":            ("Aviation",       "Airport"),
    "helipad":            ("Aviation",       "Helipad"),
    # COCO extras
    "person":             ("Person",         "Pedestrian"),
    "bicycle":            ("Vehicle",        "Bicycle"),
}

# Two sessions — DOTA OBB (satellite, default) and COCO (fallback)
# Sessions are NOT cached permanently — load on demand, release after use to free ~200MB RAM
_ort_sessions     = {}
_ort_session_lock = threading.Lock()

def _release_ort_session(model_key="dota"):
    """Drop the ONNX session from RAM.

    This is the other half of the caching decision and the two disagreed:
    _get_ort_session was changed to reuse a loaded session, but this was
    still called unconditionally after every scan and deleted it again, so
    the cache never survived a single scan. Measured effect of the reload:
    the model init landed inside the scan window and showed up as a 3.5s
    event-loop stall that disappeared once the session genuinely persisted.

    Now both halves read the same switch. Releasing is opt-in via
    ONNX_NO_PERSIST, for a deployment where the resident model matters more
    than the reload cost."""
    if not os.getenv("ONNX_NO_PERSIST"):
        return
    import gc
    with _ort_session_lock:
        if model_key in _ort_sessions:
            del _ort_sessions[model_key]
    gc.collect()

def _get_ort_session(model_key="dota"):
    with _ort_session_lock:
        # Reuse the loaded session by default. Previously this was gated
        # behind ONNX_PERSIST, so the default path re-read and re-initialised
        # the model from disk on EVERY scan — seconds of GIL-holding work
        # repeated for no benefit. Set ONNX_NO_PERSIST=1 to go back to
        # per-scan loading if a memory ceiling ever makes that necessary.
        if model_key in _ort_sessions and not os.getenv("ONNX_NO_PERSIST"):
            return _ort_sessions[model_key]
        try:
            import onnxruntime as ort
            if model_key == "dota-v2":
                fname = "yolov8m-obb.onnx"
                path  = str(BASE_DIR / fname)
                if not os.path.exists(path):
                    print(f"[overwatch] dota-v2: {fname} not found — downloading yolov8m-obb...")
                    try:
                        from ultralytics import YOLO as _YOLO
                        _m = _YOLO("yolov8m-obb.pt")
                        _m.export(format="onnx", imgsz=1024)
                        import shutil as _sh
                        _src = BASE_DIR / "yolov8m-obb.onnx"
                        if not _src.exists():
                            _src = Path("yolov8m-obb.onnx")
                        if _src.exists():
                            _sh.move(str(_src), path)
                        print(f"[overwatch] dota-v2 model ready at {path}")
                    except Exception as _dl:
                        print(f"[overwatch] dota-v2 download failed: {_dl} — falling back to nano OBB")
                        fname = "yolov8n-obb.onnx"
                        path  = str(BASE_DIR / fname)
            elif model_key == "dota":
                fname = "yolov8n-obb.onnx"
                path  = str(BASE_DIR / fname)
            else:
                fname = "yolov8n.onnx"
                path  = str(BASE_DIR / fname)
            # THREAD BUDGET. Left at ONNX Runtime's defaults, an inference
            # session claims one intra-op thread PER CORE. On an 8-core box
            # that means every core is saturated by the model and the main
            # Python thread — the one running the asyncio loop — cannot get
            # scheduled. Measured here: health probes stalled 8.0s during a
            # real scan even after the work was correctly moved off the loop
            # onto a dedicated pool. Moving work off the event loop does not
            # help if the work then takes every core; the loop needs a core,
            # not merely a different thread.
            _so = ort.SessionOptions()
            _so.intra_op_num_threads = _IMAGERY_ONNX_THREADS
            _so.inter_op_num_threads = 1
            _so.execution_mode = ort.ExecutionMode.ORT_SEQUENTIAL
            sess = ort.InferenceSession(path, sess_options=_so,
                                        providers=["CPUExecutionProvider"])
            _ort_sessions[model_key] = sess
            print(f"[overwatch] loaded {fname} (model_key={model_key}, "
                  f"intra_op_threads={_IMAGERY_ONNX_THREADS}/{os.cpu_count()})")
        except Exception as e:
            print(f"[overwatch] session load failed ({model_key}): {e}")
            _ort_sessions[model_key] = None
        return _ort_sessions[model_key]

def _ow_nms(boxes, scores, iou_threshold):
    """Axis-aligned NMS. boxes: (N,4) xyxy. Returns list of kept indices."""
    import numpy as np
    x1, y1, x2, y2 = boxes[:, 0], boxes[:, 1], boxes[:, 2], boxes[:, 3]
    areas = np.maximum(0, x2 - x1) * np.maximum(0, y2 - y1)
    order = scores.argsort()[::-1]
    keep  = []
    while order.size > 0:
        i = order[0]; keep.append(i)
        xx1 = np.maximum(x1[i], x1[order[1:]]); yy1 = np.maximum(y1[i], y1[order[1:]])
        xx2 = np.minimum(x2[i], x2[order[1:]]); yy2 = np.minimum(y2[i], y2[order[1:]])
        inter = np.maximum(0, xx2 - xx1) * np.maximum(0, yy2 - yy1)
        iou   = inter / (areas[i] + areas[order[1:]] - inter + 1e-6)
        order = order[np.where(iou <= iou_threshold)[0] + 1]
    return keep

def _ow_obb_corners(cx, cy, w, h, angle):
    """Compute 4 corner points of a rotated box. All values in pixel space."""
    cos_a, sin_a = math.cos(angle), math.sin(angle)
    hw, hh = w / 2, h / 2
    offsets = [(-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh)]
    return [(cx + dx * cos_a - dy * sin_a, cy + dx * sin_a + dy * cos_a) for dx, dy in offsets]

def _ow_lat_to_tile_y_frac(lat, zoom):
    lat_rad = math.radians(lat)
    return (1.0 - math.log(math.tan(lat_rad) + 1.0 / math.cos(lat_rad)) / math.pi) / 2.0 * (2 ** zoom)

def _ow_lon_to_tile_x_frac(lon, zoom):
    return (lon + 180.0) / 360.0 * (2 ** zoom)

def _fetch_esri_tile(z, x, y):
    from PIL import Image
    url = f"https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}"
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 HorizonWatch/1.0"})
    with urllib.request.urlopen(req, timeout=12) as r:
        return Image.open(_io.BytesIO(r.read())).convert("RGB")

def _run_overwatch_inference(bounds, zoom, confidence, enhance=False, model_key="dota"):
    """Blocking: fetch Esri tiles, stitch, crop, run ONNX, return geo detections."""
    import concurrent.futures
    import numpy as np
    from PIL import Image

    _t_start = time.monotonic()
    north, south, east, west = bounds["north"], bounds["south"], bounds["east"], bounds["west"]
    TILE_SZ  = 256
    is_dota  = model_key in ("dota", "dota-v2")
    INPUT_SZ = 1024 if is_dota else 640
    classes  = (_OW_DOTA_V2_CLASSES if model_key == "dota-v2" else
                _OW_DOTA_CLASSES    if is_dota else
                _OW_COCO_CLASSES)

    # ── Tile fetch ────────────────────────────────────────────────────────────
    x_min = int(_ow_lon_to_tile_x_frac(west,  zoom))
    x_max = int(_ow_lon_to_tile_x_frac(east,  zoom))
    y_min = int(_ow_lat_to_tile_y_frac(north, zoom))
    y_max = int(_ow_lat_to_tile_y_frac(south, zoom))
    x_min, x_max = min(x_min, x_max), max(x_min, x_max)
    y_min, y_max = min(y_min, y_max), max(y_min, y_max)

    tile_count = (x_max - x_min + 1) * (y_max - y_min + 1)

    # BUDGET IN PIXELS, BEFORE FETCHING ANYTHING.
    #
    # The previous guard allowed 10,000 tiles, which is 655 MEGAPIXELS once
    # stitched — well past PIL's own 179MP decompression-bomb ceiling. So the
    # limit sat above the point where the operation cannot succeed at all.
    # Measured: a zoom-17 request spent 312 seconds fetching thousands of
    # tiles, stitched a 600MP image, was refused by PIL, and returned zero
    # detections. The same 1.8GB stitch stalled the event loop for 13.5s
    # through sheer memory pressure.
    #
    # Refusing up front costs the user a re-draw. Refusing after five minutes
    # costs them five minutes and tells them nothing they could act on.
    est_px = ((x_max - x_min + 1) * TILE_SZ) * ((y_max - y_min + 1) * TILE_SZ)
    if est_px > _IMAGERY_MAX_STITCH_PX:
        # Say what would fit, so the message is actionable rather than "no".
        max_tiles = max(1, int(_IMAGERY_MAX_STITCH_PX // (TILE_SZ * TILE_SZ)))
        deg_per_tile = 360.0 / (2 ** zoom)
        max_span_deg = (max_tiles ** 0.5) * deg_per_tile
        km_per_deg = 111.0 * max(0.05, math.cos(math.radians((north + south) / 2)))
        suggest_zoom = zoom
        while suggest_zoom > 10 and est_px / (4 ** (zoom - suggest_zoom)) > _IMAGERY_MAX_STITCH_PX:
            suggest_zoom -= 1
        return {
            "error": (
                f"Area too large at zoom {zoom}: {tile_count} tiles would stitch to "
                f"{est_px/1e6:.0f} megapixels (budget {_IMAGERY_MAX_STITCH_PX/1e6:.0f}MP). "
                f"At this zoom the largest workable box is about "
                f"{max_span_deg * km_per_deg:.0f}km across — either draw smaller, "
                f"or use zoom {suggest_zoom}, which covers the same ground at lower detail."
            ),
            "count": 0, "detections": [],
            "budget": {"tiles": tile_count, "megapixels": round(est_px / 1e6, 1),
                       "max_megapixels": round(_IMAGERY_MAX_STITCH_PX / 1e6, 1),
                       "suggested_zoom": suggest_zoom},
        }
    if tile_count > 400:
        print(f"[overwatch] large area: {tile_count} tiles / {est_px/1e6:.0f}MP — this will take a while")

    stitch_w = (x_max - x_min + 1) * TILE_SZ
    stitch_h = (y_max - y_min + 1) * TILE_SZ
    stitched  = Image.new("RGB", (stitch_w, stitch_h))

    # 16 threads here was not a network-concurrency choice in practice: each
    # one PIL-decodes its tile on return, and PNG decode holds the GIL. The
    # fetch is I/O-bound enough that a smaller pool costs little wall-clock
    # while leaving the interpreter available to the event loop.
    with concurrent.futures.ThreadPoolExecutor(max_workers=_IMAGERY_TILE_FETCHERS) as pool:
        futs = {pool.submit(_fetch_esri_tile, zoom, x, y): (x, y)
                for x in range(x_min, x_max + 1) for y in range(y_min, y_max + 1)}
        for fut, (x, y) in futs.items():
            try:
                stitched.paste(fut.result(timeout=15), ((x - x_min) * TILE_SZ, (y - y_min) * TILE_SZ))
            except Exception as e:
                print(f"[overwatch] tile {zoom}/{x}/{y} failed: {e}")

    def lon_to_px(lon): return (_ow_lon_to_tile_x_frac(lon, zoom) - x_min) * TILE_SZ
    def lat_to_py(lat): return (_ow_lat_to_tile_y_frac(lat, zoom) - y_min) * TILE_SZ

    cx1 = int(max(0, lon_to_px(west)));  cx2 = int(min(stitch_w, lon_to_px(east)))
    cy1 = int(max(0, lat_to_py(north))); cy2 = int(min(stitch_h, lat_to_py(south)))
    if cx2 <= cx1 or cy2 <= cy1:
        return {"error": "Crop region is empty — check bounds.", "count": 0, "detections": []}

    cropped = stitched.crop((cx1, cy1, cx2, cy2))
    img_w, img_h = cropped.size
    _t_fetch = time.monotonic() - _t_start
    print(f"[overwatch] crop → {img_w}×{img_h}px zoom={zoom} model={model_key} "
          f"(fetch+stitch {_t_fetch:.1f}s)")

    # ── Tiled ONNX inference (delegates to shared helper) ────────────────────
    _t_inf = time.monotonic()
    result = _run_inference_on_image(cropped, bounds, confidence, enhance, model_key)
    # Phase timings, kept permanently: when a scan is slow, "which half" is
    # the first question, and guessing it from wall-clock alone wasted a
    # measurement cycle during this work.
    result["timing_s"] = {"fetch_stitch": round(_t_fetch, 1),
                          "inference": round(time.monotonic() - _t_inf, 1)}
    print(f"[overwatch] inference {result['timing_s']['inference']:.1f}s "
          f"→ {result.get('count', 0)} detections")
    import gc
    del stitched, cropped
    gc.collect()
    result["zoom_used"] = int(zoom)
    return result


def _decode_and_infer(image_b64: str, bounds, confidence, enhance=False,
                      model_key="dota", keep_px=False):
    """Decode a caller-supplied image and run inference — BOTH on the imagery
    pool. Base64-decoding and PIL-decoding a multi-megapixel scene is itself
    CPU-bound work measured in seconds; doing it in the endpoint coroutine
    before handing off to the pool would block the event loop for exactly the
    kind of interval this whole module exists to eliminate."""
    import base64 as _b64m
    from PIL import Image
    img = Image.open(_io.BytesIO(_b64m.b64decode(image_b64))).convert("RGB")
    print(f"[overwatch/detect-image] {img.size[0]}x{img.size[1]}px model={model_key} conf={confidence}")
    return _run_inference_on_image(img, bounds, confidence, enhance, model_key, keep_px)


def _run_inference_on_image(cropped, bounds, confidence, enhance=False, model_key="dota", keep_px=False):
    """Run tiled ONNX inference on a PIL Image cropped to `bounds`. Returns detection dict."""
    import numpy as np
    from PIL import Image

    is_dota  = model_key in ("dota", "dota-v2")
    INPUT_SZ = 1024 if is_dota else 640
    classes  = (_OW_DOTA_V2_CLASSES if model_key == "dota-v2" else
                _OW_DOTA_CLASSES    if is_dota else
                _OW_COCO_CLASSES)

    north, south, east, west = bounds["north"], bounds["south"], bounds["east"], bounds["west"]
    img_w, img_h = cropped.size

    session = _get_ort_session(model_key)
    if session is None:
        return {"error": f"ONNX session unavailable (model={model_key})", "count": 0, "detections": []}

    n_cls   = len(classes)

    # ── THE DETECTOR WAS BEING SHOWN OBJECTS TOO SMALL TO SEE ────────────
    #
    # Reported as "we only detected 7 objects while I test scanned Jebel
    # Ali port" — one of the largest container ports on earth.
    #
    # YOLOv8-OBB on DOTA was trained on aerial imagery where a ship spans
    # hundreds of pixels. Sentinel-2 is 10 m/px, so a 300m container ship
    # is 30 pixels and a storage tank is 5 — one to two orders of magnitude
    # below anything the model saw in training. Feeding it 1024px windows
    # of native-resolution imagery asks it to find objects at a scale it
    # has no features for.
    #
    # The fix is to crop a SMALLER window and let the existing letterbox
    # resize magnify it to the model's 1024 input, which is what SAHI does
    # for small-object detection. Nothing else changes: sc_t is already
    # computed from the crop size and _unpad already divides it back out,
    # so the geometry survives untouched.
    #
    # MEASURED at Jebel Ali, 907x718 native, same image, same weights:
    #
    #   zoom   detections   vessel length median / max   vessel conf
    #     1x       21            450m / 915m                0.30
    #     2x       70              -                          -
    #     3x      108            145m / 257m                0.43
    #     4x      123              -                          -
    #
    # The count is not the interesting part. At 1x the model reports
    # vessels 915m long — no such ship exists, the largest ever built is
    # 458m — because it cannot resolve individual hulls and merges a whole
    # quay into one box. At 3x the size distribution becomes physically
    # real, and median confidence RISES. Detections invented out of
    # interpolated texture would do the opposite, which is the check that
    # separates recovered objects from resampling artefacts.
    #
    # 4x buys 14% more detections for 78% more tiles, so 3x is the knee.
    # The cost is real and quadratic — 9x the inference tiles — which is
    # why it is a dial and why the tile planner reports it.
    DETECT_ZOOM = max(1, min(int(os.getenv("IMAGERY_DETECT_ZOOM", "3")), 4))
    WINDOW  = max(128, INPUT_SZ // DETECT_ZOOM)
    # Overlap scales with the window, or a 341px window at the old fixed
    # 100px would overlap by 29% and triple the tile count again.
    OVERLAP = max(24, int(WINDOW * 0.10))
    STRIDE  = WINDOW - OVERLAP

    def _tile_starts(dim):
        if dim <= WINDOW:
            return [0]
        starts = list(range(0, dim - WINDOW, STRIDE))
        if starts[-1] + WINDOW < dim:
            starts.append(dim - WINDOW)
        return starts

    xs_starts = _tile_starts(img_w)
    ys_starts = _tile_starts(img_h)
    print(f"[overwatch] tiled: {len(xs_starts)}×{len(ys_starts)}="
          f"{len(xs_starts)*len(ys_starts)} inference tiles on {img_w}×{img_h}px "
          f"(window {WINDOW}px → {INPUT_SZ}px, {DETECT_ZOOM}× detect zoom)")

    # pixel → geo helpers (full cropped image coordinate space)
    def px_lat(py): return float(north - (py / img_h) * (north - south))
    def px_lon(px): return float(west  + (px / img_w) * (east  - west))

    def _unpad(v, pad, sc, lim):
        return float(min(max((v - pad) / sc, 0.0), lim))

    all_aa_boxes   = []   # [x1,y1,x2,y2] in full-image pixels — for NMS
    all_scores     = []
    all_class_ids  = []
    all_corners_px = []   # list of [(x,y)×4] in full-image pixels — for geo conversion

    for ty in ys_starts:
        for tx in xs_starts:
            tw = min(WINDOW, img_w - tx)
            th = min(WINDOW, img_h - ty)
            tile = cropped.crop((tx, ty, tx + tw, ty + th))

            sc_t = min(INPUT_SZ / tw, INPUT_SZ / th)
            nw_t = int(tw * sc_t); nh_t = int(th * sc_t)
            px_t = (INPUT_SZ - nw_t) // 2; py_t = (INPUT_SZ - nh_t) // 2
            pad_tile = Image.new("RGB", (INPUT_SZ, INPUT_SZ), (114, 114, 114))
            pad_tile.paste(tile.resize((nw_t, nh_t), Image.BILINEAR), (px_t, py_t))

            arr_t = np.array(pad_tile, dtype=np.float32) / 255.0
            arr_t = np.transpose(arr_t, (2, 0, 1))[np.newaxis]
            del pad_tile, tile

            try:
                raw_t = session.run(None, {session.get_inputs()[0].name: arr_t})[0]
            except Exception as e:
                print(f"[overwatch] tile ({tx},{ty}) failed: {e}")
                del arr_t
                continue
            del arr_t

            pr_t = raw_t[0].T
            del raw_t
            if model_key == "dota-v2":
                # 18 classes: cols 4..21, angle at col 22
                bxy_t = pr_t[:, :4]; sc_cls = pr_t[:, 4:22]; ang_t = pr_t[:, 22]
            elif is_dota:
                # 15 classes: cols 4..18, angle at col 19
                bxy_t = pr_t[:, :4]; sc_cls = pr_t[:, 4:19]; ang_t = pr_t[:, 19]
            else:
                bxy_t = pr_t[:, :4]; sc_cls = pr_t[:, 4:]; ang_t = np.zeros(len(pr_t))

            ms_t = sc_cls.max(axis=1); ci_t = sc_cls.argmax(axis=1)
            ok   = ms_t > confidence
            if not ok.any():
                del pr_t
                continue

            bxy_ok = bxy_t[ok]; ms_ok = ms_t[ok]; ci_ok = ci_t[ok]; ang_ok = ang_t[ok]
            del pr_t

            for i in range(len(bxy_ok)):
                cx_p, cy_p, w_p, h_p = bxy_ok[i]
                angle = float(ang_ok[i])
                if is_dota:
                    pts_lb = _ow_obb_corners(cx_p, cy_p, w_p, h_p, angle)
                    corners_full = [
                        (_unpad(p[0], px_t, sc_t, tw) + tx,
                         _unpad(p[1], py_t, sc_t, th) + ty)
                        for p in pts_lb
                    ]
                    xs_f = [p[0] for p in corners_full]
                    ys_f = [p[1] for p in corners_full]
                    aa   = [min(xs_f), min(ys_f), max(xs_f), max(ys_f)]
                else:
                    x1_f = _unpad(cx_p - w_p/2, px_t, sc_t, tw) + tx
                    y1_f = _unpad(cy_p - h_p/2, py_t, sc_t, th) + ty
                    x2_f = _unpad(cx_p + w_p/2, px_t, sc_t, tw) + tx
                    y2_f = _unpad(cy_p + h_p/2, py_t, sc_t, th) + ty
                    aa   = [x1_f, y1_f, x2_f, y2_f]
                    corners_full = [(x1_f, y1_f), (x2_f, y1_f), (x2_f, y2_f), (x1_f, y2_f)]
                all_aa_boxes.append(aa)
                all_scores.append(float(ms_ok[i]))
                all_class_ids.append(int(ci_ok[i]))
                all_corners_px.append(corners_full)

    # ── Global NMS across all tiles ───────────────────────────────────────────
    detections = []
    if all_aa_boxes:
        aa_arr = np.array(all_aa_boxes, dtype=np.float32)
        sc_arr = np.array(all_scores,   dtype=np.float32)

        for idx in _ow_nms(aa_arr, sc_arr, 0.45):
            cls_id  = all_class_ids[idx]
            conf    = round(all_scores[idx], 3)
            corners = all_corners_px[idx]
            xs_f    = [p[0] for p in corners]
            ys_f    = [p[1] for p in corners]
            corners_geo = [[px_lat(y), px_lon(x)] for x, y in corners]
            center_geo  = [px_lat(sum(ys_f) / 4), px_lon(sum(xs_f) / 4)]
            px_box      = [min(xs_f), min(ys_f), max(xs_f), max(ys_f)]

            cls_name = classes[cls_id] if cls_id < n_cls else "unknown"
            cat, subcat = _OW_CATEGORY_MAP.get(cls_name, ("Object", "Unknown"))
            detections.append({
                "class":       cls_name,
                "category":    cat,
                "subcategory": subcat,
                "confidence":  conf,
                "center":      center_geo,
                "corners":     corners_geo,
                "_px":         px_box,
            })

    # Save pixel boxes before enhance/cleanup so keep_px can restore them
    _px_saved = {id(d): d.get("_px") for d in detections} if keep_px else {}

    # ── Optional Claude enhance pass ──────────────────────────────────────────
    if enhance and detections:
        import base64 as _b64
        _ant_key = os.getenv("ANTHROPIC_API_KEY")
        if _ant_key:
            try:
                _ant = anthropic.Anthropic(api_key=_ant_key)
                for det in detections[:10]:
                    x1, y1, x2, y2 = det.pop("_px")
                    pad = 20
                    crop_obj = cropped.crop((max(0, int(x1)-pad), max(0, int(y1)-pad),
                                            min(img_w, int(x2)+pad), min(img_h, int(y2)+pad)))
                    buf = _io.BytesIO(); crop_obj.save(buf, format="PNG")
                    crop_b64 = _b64.b64encode(buf.getvalue()).decode()
                    try:
                        resp = _ant.messages.create(
                            model="claude-sonnet-4-6", max_tokens=80,
                            messages=[{"role": "user", "content": [
                                {"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": crop_b64}},
                                {"type": "text", "text": f"YOLO detected '{det['class']}' in satellite imagery. Give specific type. Reply ONLY with JSON: {{\"specific_type\": \"...\"}}"},
                            ]}],
                        )
                        det["specific_type"] = _json.loads(resp.content[0].text).get("specific_type", det["class"])
                        try:
                            usage_tracker.record_call(
                                resp.usage.input_tokens, resp.usage.output_tokens,
                                call_type="overwatch_enhance", headline=det["class"],
                                model="claude-sonnet-4-6", item_id=det["class"],
                            )
                        except Exception as _ut_e:
                            print(f"[overwatch] usage_tracker record error: {_ut_e}")
                    except Exception as e_cls:
                        print(f"[overwatch] classify error: {e_cls}")
                for det in detections[10:]:
                    det.pop("_px", None)
            except Exception as e_enh:
                print(f"[overwatch] enhance error: {e_enh}")
                for det in detections: det.pop("_px", None)
        else:
            for det in detections: det.pop("_px", None)
    else:
        for det in detections: det.pop("_px", None)

    # Restore saved pixel boxes if requested
    if keep_px:
        for det in detections:
            px = _px_saved.get(id(det))
            if px is not None:
                det["_px"] = px

    print(f"[overwatch] {len(detections)} detections (model={model_key}, conf≥{confidence})")

    # Free memory explicitly — release ONNX session so ~200MB returns to OS
    import gc
    del all_aa_boxes, all_corners_px, all_scores, all_class_ids
    _release_ort_session(model_key)
    gc.collect()

    return {
        "detections": detections,
        "count":      len(detections),
        "model":      f"onnx-{model_key}",
        "enhanced":   bool(enhance),
    }


# ── _convert_overwatch_detections ─────────────────────────────────────────────

def _convert_overwatch_detections(raw_dets: list, band_type: str = "TRUE_COLOR") -> list:
    """Convert _run_overwatch_inference output to SentinelDetection schema dicts."""
    import json as _j, math as _m

    _DOTA_TO_TYPE = {
        # "large-vehicle" mapped to "vessel" here until 2026-09-19. DOTA's
        # large-vehicle is a truck or bus; the label map above this file's
        # inference code has always called it Heavy Vehicle. The effect was
        # that every heavy road vehicle in a scan was stored and reported as
        # a SHIP — which matters most exactly where vehicles matter, since a
        # convoy would have been filed as a fleet.
        "ship": "vessel", "large-vehicle": "vehicle", "small-vehicle": "vehicle",
        "plane": "aircraft", "helicopter": "aircraft",
        "storage-tank": "infrastructure_change", "swimming-pool": "infrastructure_change",
        "harbor": "infrastructure_change", "bridge": "infrastructure_change",
        "ground-track-field": "infrastructure_change", "basketball-court": "infrastructure_change",
        "soccer-ball-field": "infrastructure_change", "roundabout": "infrastructure_change",
        "tennis-court": "infrastructure_change", "baseball-diamond": "infrastructure_change",
    }

    def _hav(lat1, lon1, lat2, lon2):
        R = 6_371_000
        dl = _m.radians(lat2 - lat1); dg = _m.radians(lon2 - lon1)
        a = _m.sin(dl/2)**2 + _m.cos(_m.radians(lat1)) * _m.cos(_m.radians(lat2)) * _m.sin(dg/2)**2
        return R * 2 * _m.asin(_m.sqrt(a))

    results = []
    for d in raw_dets:
        center  = d.get("center", [0, 0])   # [lat, lon]
        corners = d.get("corners", [])
        cls     = d.get("class", "unknown")
        conf    = float(d.get("confidence", 0.0))
        obj_type = _DOTA_TO_TYPE.get(cls, cls.replace("-", "_").lower())

        geo_geometry = est_length_m = est_width_m = area_m2 = None
        if corners:
            lats = [c[0] for c in corners]; lons = [c[1] for c in corners]
            ring = [[min(lons), min(lats)], [max(lons), min(lats)],
                    [max(lons), max(lats)], [min(lons), max(lats)], [min(lons), min(lats)]]
            geo_geometry = _j.dumps({"type": "Polygon", "coordinates": [ring]})
            lat_m = _hav(min(lats), min(lons), max(lats), min(lons))
            lon_m = _hav(min(lats), min(lons), min(lats), max(lons))
            area_m2      = round(lat_m * lon_m, 1)
            est_length_m = round(max(lat_m, lon_m), 1)
            est_width_m  = round(min(lat_m, lon_m), 1)

        sev        = "high"      if conf > 0.7 else ("medium" if conf > 0.4 else "info")
        alert_tier = "immediate" if conf > 0.7 and obj_type == "vessel" else (
                     "digest"    if conf > 0.35 else "silent")

        results.append({
            "object_type":   obj_type,
            "confidence":    round(conf, 3),
            "centroid_lat":  round(float(center[0]), 6),
            "centroid_lon":  round(float(center[1]), 6),
            "geo_geometry":  geo_geometry,
            "area_m2":       area_m2,
            "severity":      sev,
            "alert_tier":    alert_tier,
            "matched_to_ais": False,
            "attributes":    _j.dumps({
                "class":             cls,
                "category":          d.get("category", "Object"),
                "subcategory":       d.get("subcategory", ""),
                "estimated_length_m": est_length_m,
                "estimated_width_m":  est_width_m,
                "band_type":         band_type,
            }),
        })
    return results


# ── _run_overwatch_detection_sync ─────────────────────────────────────────────

def _run_overwatch_detection_sync(bbox: dict, band_type: str = "TRUE_COLOR",
                                   confidence: float = 0.15) -> list:
    """Blocking detection for TRUE_COLOR band via ESRI DOTA YOLO."""
    west  = float(bbox["min_lon"])
    south = float(bbox["min_lat"])
    east  = float(bbox["max_lon"])
    north = float(bbox["max_lat"])
    bounds = {"north": north, "south": south, "east": east, "west": west}

    result = _run_overwatch_inference(bounds, zoom=17, confidence=confidence,
                                      enhance=False, model_key="dota")
    if result.get("error"):
        print(f"[overwatch_detection] ESRI error: {result['error']}")
        return []
    return _convert_overwatch_detections(result.get("detections", []), "TRUE_COLOR")


@app.post("/api/overwatch/detect")
async def overwatch_detect(request: Request):
    """Fetch Esri satellite tiles, run ONNX YOLOv8 (DOTA OBB default), return geo detections."""
    try:
        body       = await request.json()
        bounds     = body.get("bounds")
        zoom       = int(body.get("zoom", 15))
        confidence = float(body.get("confidence", 0.15))   # lower default for aerial
        enhance    = bool(body.get("enhance", False))
        _m = body.get("model", "dota")
        model_key  = "coco" if _m == "coco" else ("dota-v2" if _m == "dota-v2" else "dota")
        if not bounds or not all(k in bounds for k in ("north", "south", "east", "west")):
            return JSONResponse({"error": "bounds {north,south,east,west} required", "count": 0, "detections": []})
        zoom = max(10, min(zoom, 18))
        # Imagery CPU work goes to the dedicated single-worker pool, never to
        # the default executor — that one is shared with every sync endpoint
        # in the app, and a large Esri scan running there starves all of them.
        try:
            result = await _imagery_rt.run_cpu(
                _run_overwatch_inference, bounds, zoom, confidence, enhance, model_key,
                label=f"overwatch:{model_key}:z{zoom}",
            )
        except _imagery_rt.ImageryBusy as busy:
            return JSONResponse({"error": str(busy), "count": 0, "detections": [], "busy": True},
                                status_code=429)
        except _imagery_rt.ImageryTimeout as slow:
            return JSONResponse({"error": str(slow), "count": 0, "detections": []}, status_code=504)
        return JSONResponse(result)
    except Exception as e:
        print(f"[overwatch] endpoint error: {e}")
        return JSONResponse({"error": str(e), "count": 0, "detections": []})


@app.post("/api/overwatch/detect-image")
async def overwatch_detect_image(request: Request):
    """Run ONNX inference on a caller-supplied base64 PNG (e.g. Sentinel-2 image)."""
    import base64 as _b64
    import functools
    try:
        body       = await request.json()
        image_b64  = body.get("image", "")
        bounds     = body.get("bounds")
        confidence = float(body.get("confidence", 0.15))
        enhance    = bool(body.get("enhance", False))
        _m = body.get("model", "dota")
        model_key  = "coco" if _m == "coco" else ("dota-v2" if _m == "dota-v2" else "dota")

        if not image_b64 or not bounds or not all(k in bounds for k in ("north", "south", "east", "west")):
            return JSONResponse({"error": "image (base64) and bounds {north,south,east,west} required", "count": 0, "detections": []})

        # Strip optional data-URL prefix
        if "," in image_b64:
            image_b64 = image_b64.split(",", 1)[1]

        try:
            result = await _imagery_rt.run_cpu(
                _decode_and_infer, image_b64, bounds, confidence, enhance, model_key,
                label=f"overwatch-image:{model_key}",
            )
        except _imagery_rt.ImageryBusy as busy:
            return JSONResponse({"error": str(busy), "count": 0, "detections": [], "busy": True},
                                status_code=429)
        except _imagery_rt.ImageryTimeout as slow:
            return JSONResponse({"error": str(slow), "count": 0, "detections": []}, status_code=504)
        result["zoom_used"] = None   # no tile zoom — image supplied directly
        return JSONResponse(result)
    except Exception as e:
        print(f"[overwatch/detect-image] error: {e}")
        return JSONResponse({"error": str(e), "count": 0, "detections": []})


@app.post("/api/overwatch/scans")
async def overwatch_scans_create(request: Request):
    """Persist a completed Overwatch scan record for analytics."""
    import json as _json
    try:
        from backend.database import OverwatchScanRecord
    except ImportError:
        from database import OverwatchScanRecord
    try:
        body = await request.json()
        with get_db() as db:
            rec = OverwatchScanRecord(
                zone_name      = body.get("zone_name"),
                bounds_json    = _json.dumps(body.get("bounds")) if body.get("bounds") else None,
                polygon_json   = _json.dumps(body.get("polygon")) if body.get("polygon") else None,
                total          = int(body.get("total", 0)),
                by_category    = _json.dumps(body.get("by_category", {})),
                avg_confidence = body.get("avg_confidence"),
                imagery_source = body.get("imagery_source"),
                imagery_type   = body.get("imagery_type"),
                model_used     = body.get("model_used"),
            )
            db.add(rec)
            db.commit()
            db.refresh(rec)
            return JSONResponse({"id": rec.id, "created_at": rec.created_at.isoformat()})
    except Exception as e:
        print(f"[overwatch/scans POST] error: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)


@app.get("/api/overwatch/scans")
def overwatch_scans_list(request: Request, limit: int = 50):
    """Return recent Overwatch scan records for analytics charts."""
    import json as _json
    try:
        from backend.database import OverwatchScanRecord
    except ImportError:
        from database import OverwatchScanRecord
    try:
        with get_db() as db:
            rows = db.query(OverwatchScanRecord).order_by(OverwatchScanRecord.created_at.desc()).limit(limit).all()
            records = []
            for r in rows:
                records.append({
                    "id":             r.id,
                    "zone_name":      r.zone_name,
                    "total":          r.total,
                    "by_category":    _json.loads(r.by_category) if r.by_category else {},
                    "avg_confidence": r.avg_confidence,
                    "imagery_source": r.imagery_source,
                    "imagery_type":   r.imagery_type,
                    "model_used":     r.model_used,
                    "created_at":     r.created_at.isoformat() if r.created_at else None,
                })
            return JSONResponse({"scans": records})
    except Exception as e:
        print(f"[overwatch/scans GET] error: {e}")
        return JSONResponse({"scans": [], "error": str(e)})


@app.post("/api/overwatch/analyze")
async def overwatch_analyze(request: Request):
    """Claude intelligence assessment of Overwatch detection results."""
    try:
        body       = await request.json()
        detections = body.get("detections", [])
        bounds     = body.get("bounds", {})
        if not detections:
            return JSONResponse({"error": "No detections to analyze"})
        # Summarise by specific_type > class
        summary: dict = {}
        for d in detections:
            cls = d.get("specific_type") or d.get("class", "unknown")
            summary[cls] = summary.get(cls, 0) + 1
        center_lat = (bounds.get("north", 0) + bounds.get("south", 0)) / 2
        center_lon = (bounds.get("east", 0)  + bounds.get("west", 0))  / 2
        prompt = f"""You are a senior geospatial intelligence analyst. Analyze the following satellite imagery detection results.

Location: approximately {center_lat:.4f}°N, {center_lon:.4f}°E

Objects detected:
{_json.dumps(summary, indent=2)}

Total: {len(detections)} objects

Provide a concise intelligence assessment:
1. What facility/area is this likely to be? (airport, port, military base, industrial zone, etc.)
2. What is the operational significance of what we see?
3. Any notable observations (unusual concentrations, military assets, strategic implications)?
4. If near known conflict zones or chokepoints, what is the relevance?

Write in intelligence briefing style — 3–4 paragraphs maximum."""

        client = anthropic.Anthropic()
        resp   = client.messages.create(
            model="claude-sonnet-4-6",
            max_tokens=600,
            messages=[{"role": "user", "content": prompt}],
        )
        return JSONResponse({"analysis": resp.content[0].text, "summary": summary})
    except Exception as e:
        print(f"[overwatch/analyze] error: {e}")
        return JSONResponse({"error": str(e)})


async def _sentinel_zone_scheduler_loop():
    """Background loop: every 15 minutes, trigger scans for due WatchZones."""
    import asyncio as _asyncio_sched
    await _asyncio_sched.sleep(165)  # staggered startup
    _sched_interval = 15 * 60  # 15 minutes

    while True:
        try:
            await _asyncio_sched.sleep(_sched_interval)
            from database import WatchZone, get_db as _gdb
            now_sched = datetime.now(timezone.utc).replace(tzinfo=None)
            with _gdb() as _db:
                due_zones = (
                    _db.query(WatchZone)
                    .filter(
                        WatchZone.enabled == True,
                        WatchZone.next_scan_at <= now_sched,
                    )
                    .all()
                )
                zone_data = [
                    {
                        "id": z.id, "system_id": z.system_id, "name": z.name,
                        "bbox_min_lon": z.bbox_min_lon, "bbox_min_lat": z.bbox_min_lat,
                        "bbox_max_lon": z.bbox_max_lon, "bbox_max_lat": z.bbox_max_lat,
                        "ml_tasks": z.ml_tasks, "scan_interval_hours": z.scan_interval_hours,
                        "alert_threshold": z.alert_threshold,
                        "sensor_preference": getattr(z, "sensor_preference", None) or "sentinel2_optical",
                    }
                    for z in due_zones
                ]

            # Real root-cause-fix consolidation: this loop had its own
            # second copy of the exact "wrap SentinelScanner.run_scan in a
            # background task" launcher (_run_zone), independent of the one
            # the manual scan-now/zone-creation endpoints use
            # (_launch_zone_scan_background) — reusing that single real
            # function here too, both for consistency and to get its real
            # sensor-pipeline gate for free (a zone left on a non-deployed
            # sensor no longer gets silently retried every 15 minutes
            # forever with no real chance of succeeding).
            for zd in zone_data:
                print(f"[sentinel-scheduler] Scan triggered for zone {zd['system_id']} ({zd['name']})")
                _launch_zone_scan_background(zd, "schedule")

            # ── FIRMS: a fire is a reason to look ────────────────────────
            #
            # A thermal hotspot says SOMETHING IS BURNING; only a picture says
            # what. So a credible fire inside a watch zone tasks imagery over
            # that zone ahead of its next scheduled pass.
            #
            # Scoped to the user's OWN zones rather than polled globally,
            # which is both the relevance test and the quota guard: FIRMS
            # reports tens of thousands of detections a day worldwide, nearly
            # all of them agricultural burning, and tasking imagery on all of
            # them would exhaust Copernicus inside a day.
            try:
                await _firms_trigger_pass()
            except Exception as _fe:
                print(f"[firms] trigger pass failed: {_fe}")

            # ── Corroboration: agreement is a stronger reason than any
            # single feed. FIRMS above acts on one sensor; this acts when
            # two independent ways of looking put something in the same
            # place within hours.
            try:
                await _corroboration_trigger_pass()
            except Exception as _ce2:
                print(f"[corroborate] trigger pass failed: {_ce2}")

            # ── Radar change, on its own slow cadence. An optical scan says
            # what is there; only a comparison says what is DIFFERENT, which
            # is the question a standing watch exists to ask.
            try:
                await _change_detect_pass()
            except Exception as _che:
                print(f"[change] scheduled pass failed: {_che}")

        except Exception as _sched_e:
            print(f"[sentinel-scheduler] loop error: {_sched_e}")
            await _asyncio_sched.sleep(60)


# Locations FIRMS has already caused us to scan, so a nightly gas flare at a
# refinery does not re-task imagery every single night for ever.
_FIRMS_RECENT: list[dict] = []
_FIRMS_RECENT_MAX = 500


# Places a corroborated cluster has already caused us to look, so the same
# agreement does not re-task imagery on every pass of the scheduler.
_CORROBORATION_ACTED: list[dict] = []
_CORROBORATION_ACTED_MAX = 300
CORROBORATION_SUPPRESS_HOURS = 48
CORROBORATION_SUPPRESS_KM = 3.0


# When each zone last had a radar change pass run over it. Change detection
# costs 12-18 Sentinel Hub requests, so it runs on its own slow cadence
# rather than alongside every scheduled optical scan.
_CHANGE_LAST_RUN: dict = {}
CHANGE_INTERVAL_DAYS = float(os.getenv("CHANGE_DETECT_INTERVAL_DAYS", "7"))
CHANGE_MAX_ZONES_PER_PASS = int(os.getenv("CHANGE_DETECT_MAX_ZONES", "2"))


async def _change_detect_pass() -> None:
    """Run radar change detection over watch zones, slowly.

    THIS IS THE "EYES ON THE EARTH" BEHAVIOUR. An optical scan answers what
    is there now; only a comparison answers what is DIFFERENT, and that is
    the question a standing watch exists to ask. Until now it ran only when
    someone pressed a button, which makes it a tool rather than a watch.

    Deliberately slow and capped. Each pass is roughly a dozen Sentinel Hub
    requests per zone, and structural change is not an hourly phenomenon —
    a building does not appear between two passes of a satellite. Weekly per
    zone, at most two zones per tick, so a large watch list degrades into a
    longer rotation rather than a quota exhaustion.
    """
    import datetime as _dtc2

    from database import WatchZone, get_db as _gdbch

    if not _SENTINEL_IMAGERY_ENABLED:
        return

    now = _dtc2.datetime.now(_dtc2.timezone.utc)
    with _gdbch() as _db:
        zones = _db.query(WatchZone).filter(WatchZone.enabled == True).all()  # noqa: E712
        zone_data = [{
            "id": z.id, "system_id": z.system_id, "name": z.name,
            "west": z.bbox_min_lon, "south": z.bbox_min_lat,
            "east": z.bbox_max_lon, "north": z.bbox_max_lat,
        } for z in zones
            if None not in (z.bbox_min_lon, z.bbox_min_lat, z.bbox_max_lon, z.bbox_max_lat)]

    due = []
    for zd in zone_data:
        last = _CHANGE_LAST_RUN.get(zd["system_id"])
        if last is None or (now - last).total_seconds() >= CHANGE_INTERVAL_DAYS * 86400:
            due.append(zd)
    if not due:
        return

    # Oldest first, so a long watch list rotates fairly instead of always
    # servicing whichever zone happens to sort first.
    due.sort(key=lambda z: _CHANGE_LAST_RUN.get(z["system_id"], _dtc2.datetime.min.replace(tzinfo=_dtc2.timezone.utc)))

    for zd in due[:CHANGE_MAX_ZONES_PER_PASS]:
        _CHANGE_LAST_RUN[zd["system_id"]] = now
        bounds = {"west": zd["west"], "south": zd["south"],
                  "east": zd["east"], "north": zd["north"]}
        post_end = now.date().isoformat()
        pre_end = (now.date() - _dtc2.timedelta(days=90)).isoformat()
        job_id = f"chg-auto-{uuid.uuid4().hex[:8]}"
        print(f"[change] scheduled radar change pass over {zd['system_id']} "
              f"({pre_end} → {post_end})")
        asyncio.create_task(_run_pwtt_job(
            job_id, bounds, pre_end, post_end, 5, 1.63, "both", 448, zd["id"]))


async def _corroboration_trigger_pass() -> None:
    """Agreement between independent sources is a reason to point a camera.

    THE TIP-AND-CUE LOOP, CLOSED. FIRMS already tasks imagery on a credible
    fire, which is one sensor acting alone. This is the stronger signal:
    two genuinely different ways of looking — thermal and radar, or an
    instrument and a human watching a video — putting something at the same
    coordinate within hours. That is a better reason to spend a scan than
    any single feed, and until now nothing acted on it.

    Scoped to the analyst's own watch zones, which is both the relevance
    test and the quota guard: the world produces corroborated clusters all
    day and almost none of them are anyone's concern.
    """
    import corroborate as _co
    from database import WatchZone, get_db as _gdbc

    if not _SENTINEL_IMAGERY_ENABLED:
        return

    now = datetime.now(timezone.utc).replace(tzinfo=None)
    cutoff = now - timedelta(hours=CORROBORATION_SUPPRESS_HOURS)
    global _CORROBORATION_ACTED
    _CORROBORATION_ACTED = [p for p in _CORROBORATION_ACTED if p.get("at", now) >= cutoff]

    with _gdbc() as _db:
        zones = _db.query(WatchZone).filter(WatchZone.enabled == True).all()  # noqa: E712
        zone_data = [{
            "id": z.id, "system_id": z.system_id, "name": z.name,
            "bbox_min_lon": z.bbox_min_lon, "bbox_min_lat": z.bbox_min_lat,
            "bbox_max_lon": z.bbox_max_lon, "bbox_max_lat": z.bbox_max_lat,
            "ml_tasks": z.ml_tasks, "scan_interval_hours": z.scan_interval_hours,
            "alert_threshold": z.alert_threshold,
            "sensor_preference": getattr(z, "sensor_preference", None) or "sentinel2_optical",
        } for z in zones
            if None not in (z.bbox_min_lon, z.bbox_min_lat, z.bbox_max_lon, z.bbox_max_lat)]

    if not zone_data:
        return

    clusters = _co.corroborated_only(_co.cluster(_gather_observations(hours=72)))
    if not clusters:
        return

    for zd in zone_data:
        inside = [c for c in clusters
                  if zd["bbox_min_lat"] <= c["lat"] <= zd["bbox_max_lat"]
                  and zd["bbox_min_lon"] <= c["lon"] <= zd["bbox_max_lon"]]
        if not inside:
            continue
        # Strongest first: independence, then confidence.
        top = inside[0]

        # Already looked here recently. A cluster persists for as long as
        # its members do, so without this the same agreement re-tasks a
        # scan on every fifteen-minute tick for two days.
        if any(_co.haversine_km(top["lat"], top["lon"], p["lat"], p["lon"])
               <= CORROBORATION_SUPPRESS_KM for p in _CORROBORATION_ACTED):
            continue

        print(f"[corroborate] {len(inside)} corroborated finding(s) in "
              f"{zd['system_id']} — strongest: {top['headline']}; tasking imagery")
        _CORROBORATION_ACTED.append({"lat": top["lat"], "lon": top["lon"], "at": now})
        del _CORROBORATION_ACTED[:-_CORROBORATION_ACTED_MAX]

        try:
            write_alert({
                "source": "CORROBORATED",
                "alert_type": "Multi-source agreement",
                # The headline already names what agreed and how far apart,
                # which is what makes this actionable without opening it.
                "title": f"{top['headline']} — {zd['name']}",
                "severity": "high" if top["independent_modalities"] >= 3 else "medium",
                "lat": top["lat"], "lon": top["lon"],
                "entity_type": "corroborated_finding", "region": None,
                "raw_json": {"zone_id": zd["system_id"], "cluster": top,
                             "also_in_zone": len(inside)},
            })
        except Exception as e:                              # noqa: BLE001
            print(f"[corroborate] alert failed for {zd['system_id']}: {e}")

        _launch_zone_scan_background(zd, "corroborated")


async def _firms_trigger_pass() -> None:
    """Poll FIRMS over each enabled watch zone and scan the ones that are alight."""
    import firms as _firms
    if not _firms.available():
        return          # no key configured; the feed simply is not running
    if not _SENTINEL_IMAGERY_ENABLED:
        return          # nothing to task; do not burn the FIRMS quota either

    from database import WatchZone, get_db as _gdb_firms
    loop = _asyncio_sched.get_running_loop()
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    cutoff = now - timedelta(hours=_firms.REPEAT_SUPPRESS_HOURS)
    global _FIRMS_RECENT
    _FIRMS_RECENT = [p for p in _FIRMS_RECENT if p.get("at", now) >= cutoff]

    with _gdb_firms() as _db:
        zones = (_db.query(WatchZone)
                 .filter(WatchZone.enabled == True)  # noqa: E712
                 .all())
        zone_data = [{
            "id": z.id, "system_id": z.system_id, "name": z.name,
            "bbox_min_lon": z.bbox_min_lon, "bbox_min_lat": z.bbox_min_lat,
            "bbox_max_lon": z.bbox_max_lon, "bbox_max_lat": z.bbox_max_lat,
            "ml_tasks": z.ml_tasks, "scan_interval_hours": z.scan_interval_hours,
            "alert_threshold": z.alert_threshold,
            "sensor_preference": getattr(z, "sensor_preference", None) or "sentinel2_optical",
        } for z in zones
            if None not in (z.bbox_min_lon, z.bbox_min_lat, z.bbox_max_lon, z.bbox_max_lat)]

    for zd in zone_data:
        bbox = (zd["bbox_min_lon"], zd["bbox_min_lat"], zd["bbox_max_lon"], zd["bbox_max_lat"])
        # Network call, off the event loop.
        result = await loop.run_in_executor(_executor, lambda b=bbox: _firms.fetch_area(b, days=1))
        if result.get("status") != "ok" or not result.get("fires"):
            continue
        centre = {"lat": (bbox[1] + bbox[3]) / 2, "lon": (bbox[0] + bbox[2]) / 2,
                  "label": zd["name"], "system_id": zd["system_id"]}
        # A fire anywhere in the zone is relevant BY CONSTRUCTION — the zone
        # is the analyst's own statement of what they care about. The radius
        # is sized to the zone rather than a fixed 5km.
        span_km = _firms.haversine_km(bbox[1], bbox[0], bbox[3], bbox[2])
        hits = _firms.triggers(result["fires"], [centre], _FIRMS_RECENT,
                               radius_km=max(_firms.RELEVANCE_RADIUS_KM, span_km))
        if not hits:
            continue
        top = hits[0]
        print(f"[firms] {len(hits)} credible fire(s) in {zd['system_id']} — "
              f"strongest {top.get('frp')}MW at {top['lat']:.3f},{top['lon']:.3f}; tasking imagery")

        # PERSIST THE FIRES. They used to exist only in the in-memory
        # suppression list, so a restart forgot every fire the system had
        # ever seen: nothing to draw on the map, nothing to review, and —
        # the one that matters — nothing for a fire to corroborate with,
        # because corroboration needs both observations to still exist.
        try:
            import hashlib as _hl
            from database import FireDetection, get_db as _gdbf
            with _gdbf() as _fdb:
                for h in hits:
                    # Stable id from what identifies the observation, so the
                    # same hotspot re-read from the feed is not stored twice.
                    fid = _hl.md5(
                        f"{h['lat']:.5f}|{h['lon']:.5f}|{h.get('acq_date')}|"
                        f"{h.get('acq_time')}|{h.get('satellite')}".encode()
                    ).hexdigest()[:20]
                    if _fdb.query(FireDetection).filter(
                            FireDetection.fire_id == fid).first():
                        continue
                    _fdb.add(FireDetection(
                        fire_id=fid, lat=h["lat"], lon=h["lon"],
                        brightness_k=h.get("brightness_k"),
                        confidence=str(h.get("confidence") or ""),
                        frp=h.get("frp"), satellite=h.get("satellite"),
                        instrument=h.get("instrument"),
                        source=result.get("source"),
                        acquired_at=_firms.fire_time(h).replace(tzinfo=None)
                        if _firms.fire_time(h) else now,
                        zone_system_id=zd["system_id"], triggered_scan=True,
                    ))
                _fdb.commit()
        except Exception as _fe2:
            print(f"[firms] could not persist fires for {zd['system_id']}: {_fe2}")

        for h in hits[:20]:
            _FIRMS_RECENT.append({"lat": h["lat"], "lon": h["lon"], "at": now})
        del _FIRMS_RECENT[:-_FIRMS_RECENT_MAX]
        _launch_zone_scan_background(zd, "firms_fire")

        # A FIRE BECOMES A STANDING AREA OF INTEREST, AND SAYS SO.
        #
        # The chain above scanned once and stopped. Nothing recorded
        # that the same ground should be looked at again tomorrow, so
        # the one thing imagery is actually good at — did this change —
        # was never asked. watch_zones already had every field needed
        # for a recurring scan and exactly one row in it, written by
        # hand; nothing was writing to it.
        #
        # Deduplicated first, because a single fire front produces
        # dozens of hotspot pixels across several passes and one AOI
        # each would scan the same ground a dozen times over, spending
        # Sentinel quota and raising a dozen alerts. See firms_aoi.
        try:
            import firms_aoi as _fa
            from database import WatchZone as _WZ, get_db as _gdbz
            import json as _jz
            import datetime as _dtz
            with _gdbz() as _zdb:
                existing = _zdb.query(_WZ).filter(_WZ.enabled == True).all()  # noqa: E712
                made = 0
                for fire in _fa.dedupe_fires(hits):
                    flat, flon = float(fire["lat"]), float(fire["lon"])
                    if not _fa.should_create(flat, flon, existing):
                        # Covered already — push its next scan forward so
                        # a still-burning fire keeps its area watched.
                        near, _km = _fa.nearest_existing(flat, flon, existing)
                        if near is not None:
                            near.next_scan_at = now + _dtz.timedelta(
                                hours=_fa.SCAN_INTERVAL_HOURS)
                        continue
                    box = _fa.bbox_for(flat, flon)
                    zid = f"FIRE-{abs(hash((round(flat, 3), round(flon, 3)))) % 10**8:08d}"
                    row = _WZ(
                        system_id=zid,
                        name=_fa.zone_name_for(fire),
                        description=_fa.fire_alert_text(fire),
                        polygon_geojson=_jz.dumps(_fa.polygon_for(flat, flon)),
                        bbox_min_lon=box["min_lon"], bbox_min_lat=box["min_lat"],
                        bbox_max_lon=box["max_lon"], bbox_max_lat=box["max_lat"],
                        priority="high", scan_interval_hours=_fa.SCAN_INTERVAL_HOURS,
                        enabled=True, created_by="firms",
                        next_scan_at=now + _dtz.timedelta(hours=_fa.SCAN_INTERVAL_HOURS),
                        ml_tasks=_jz.dumps(["ship_detection", "object_detection"]),
                        alert_threshold="both",
                        # Its own class, so pruning a stale fire AOI can
                        # never delete an area somebody drew by hand.
                        aoi_class=_fa.AOI_CLASS, status="active",
                        sensor_preference="sentinel2_optical",
                    )
                    _zdb.add(row)
                    existing.append(row)
                    made += 1

                    # TELL SOMEBODY, WITH THE REASON ATTACHED. Standing
                    # rule here: a notification carries why it is
                    # relevant, never just that something happened.
                    try:
                        write_alert({
                            "title": f"Fire detected — {zd['name']}",
                            "source": "imagery",
                            "alert_type": "firms_fire_aoi",
                            "severity": "medium",
                            "lat": flat, "lon": flon,
                            "region": zd["name"],
                            "entity_type": "aoi", "entity_id": zid,
                            "entity_name": row.name,
                            "tags": ["firms", "fire", "recurring-scan"],
                            "raw": {"reason": _fa.fire_alert_text(fire),
                                    "fire": fire, "aoi": zid,
                                    "rescan_hours": _fa.SCAN_INTERVAL_HOURS},
                        })
                    except Exception as _ae:
                        print(f"[firms] AOI alert failed for {zid}: {_ae}")

                # PRUNE. An AOI created by a fire that stopped burning
                # three weeks ago is quota spent on nothing.
                cutoff = now - _dtz.timedelta(days=_fa.EXPIRE_DAYS)
                stale = (_zdb.query(_WZ)
                         .filter(_WZ.aoi_class == _fa.AOI_CLASS,
                                 _WZ.enabled == True,                  # noqa: E712
                                 _WZ.created_at < cutoff)
                         .all())
                for z in stale:
                    z.enabled = False
                    z.status = "expired"
                _zdb.commit()
                if made or stale:
                    print(f"[firms] {made} new recurring AOI(s), "
                          f"{len(stale)} expired")
        except Exception as _ze:
            print(f"[firms] could not maintain fire AOIs: {_ze}")


def _auto_ingest() -> None:
    """
    Checks each reference table and runs ingestion/seeding if empty.
    Runs in a thread executor — safe to block.
    """
    import sys as _sys
    _be_dir = os.path.dirname(__file__)
    if _be_dir not in _sys.path:
        _sys.path.insert(0, _be_dir)

    from database import (
        CableSegment, LandingPoint, PortBoundary, Airport,
        RegionDefinition, RuleConfig, OntologyEntity, SessionLocal as _SL,
    )

    def _count(model):
        with _SL() as _db:
            return _db.query(model).count()

    # 1. Regions
    if _count(RegionDefinition) == 0:
        print("[auto-ingest] Regions: seeding …")
        try:
            from ingest_cables import populate_regions, REGION_DEFS
            with _SL() as _db:
                populate_regions(_db)
            print(f"[auto-ingest] Regions: {len(REGION_DEFS)} seeded")
        except Exception as _e:
            print(f"[auto-ingest] Regions seed failed: {_e}")
    else:
        print(f"[auto-ingest] Regions: {_count(RegionDefinition)} present, skipping")

    # 2 & 3. Cables + Landing Points
    cable_count = _count(CableSegment)
    if cable_count == 0:
        print("[auto-ingest] Cables: ingesting from TeleGeography…")
        try:
            from ingest_cables import run_ingest as _ingest_cables
            stats = _ingest_cables()
            print(f"[auto-ingest] Cables: {stats}")
        except Exception as _e:
            print(f"[auto-ingest] Cables ingest failed: {_e}")
    else:
        print(f"[auto-ingest] Cables: {cable_count} present, skipping")

    # 4. Ports
    port_count = _count(PortBoundary)
    if port_count == 0:
        print("[auto-ingest] Ports: ingesting from UN LOCODE…")
        try:
            from ingest_ports import run_ingest as _ingest_ports
            stats = _ingest_ports()
            print(f"[auto-ingest] Ports: {stats}")
        except Exception as _e:
            print(f"[auto-ingest] Ports ingest failed: {_e}")
    else:
        print(f"[auto-ingest] Ports: {port_count} present, skipping")

    # 5. Airports
    arpt_count = _count(Airport)
    if arpt_count == 0:
        print("[auto-ingest] Airports: ingesting from OurAirports…")
        try:
            from ingest_airports import run_ingest as _ingest_airports
            stats = _ingest_airports()
            print(f"[auto-ingest] Airports: {stats}")
        except Exception as _e:
            print(f"[auto-ingest] Airports ingest failed: {_e}")
    else:
        print(f"[auto-ingest] Airports: {arpt_count} present, skipping")

    # 6. Rules
    rule_count = _count(RuleConfig)
    if rule_count == 0:
        print("[auto-ingest] Rules: seeding canonical rule set…")
        try:
            from seed_rules import seed_db as _seed_rules
            stats = _seed_rules()
            print(f"[auto-ingest] Rules: {stats}")
        except Exception as _e:
            print(f"[auto-ingest] Rules seed failed: {_e}")
    else:
        print(f"[auto-ingest] Rules: {rule_count} present, skipping")

    # 7. OntologyEntity minimum check
    onto_count = _count(OntologyEntity)
    expected_min = 100
    if onto_count < expected_min:
        print(f"[auto-ingest] OntologyEntity: {onto_count} < {expected_min} expected — re-running ontology registration …")
        try:
            from ingest_cables import register_ontology_entities as _reg_cables
            from ingest_ports import register_ontology_entities as _reg_ports
            from ingest_airports import register_ontology_entities as _reg_airports
            with _SL() as _db:
                n_c = _reg_cables(_db)
                n_p = _reg_ports(_db)
                n_a = _reg_airports(_db)
            print(f"[auto-ingest] Ontology re-registered: cables={n_c} ports={n_p} airports={n_a}")
        except Exception as _e:
            print(f"[auto-ingest] Ontology re-registration failed: {_e}")
    else:
        print(f"[auto-ingest] OntologyEntity: {onto_count} present, ok")

    # 8. Chokepoints in OntologyEntity
    try:
        with _SL() as _db:
            choke_in_onto = _db.query(OntologyEntity).filter(
                OntologyEntity.entity_type == "Chokepoint"
            ).count()
        if choke_in_onto < len(_CHOKEPOINT_DEFS):
            print(f"[auto-ingest] Chokepoints: {choke_in_onto}/{len(_CHOKEPOINT_DEFS)} — seeding …")
            with _SL() as _db:
                for cp in _CHOKEPOINT_DEFS:
                    sid = cp["system_id"]
                    existing = _db.query(OntologyEntity).filter(
                        OntologyEntity.system_id == sid
                    ).first()
                    poly_coords = cp.get("polygon", [])
                    meta = _json.dumps({
                        "lat": cp.get("lat") or cp.get("center_lat"),
                        "lon": cp.get("lon") or cp.get("center_lng"),
                        "polygon": poly_coords,
                        "polygon_bounds": cp.get("polygon_bounds"),
                        "threat_level": cp.get("threat_level", "standard"),
                    })
                    if existing:
                        existing.entity_metadata = meta
                    else:
                        _db.add(OntologyEntity(
                            system_id       = sid,
                            entity_type     = "Chokepoint",
                            name            = cp["name"],
                            infra_type      = "Chokepoint",
                            entity_metadata = meta,
                        ))
                _db.commit()
            print(f"[auto-ingest] Chokepoints: seeded {len(_CHOKEPOINT_DEFS)} entries")
        else:
            print(f"[auto-ingest] Chokepoints: {choke_in_onto} present, ok")
    except Exception as _e:
        print(f"[auto-ingest] Chokepoints seed failed: {_e}")

    # 9. Strategic Zones baseline
    try:
        with _SL() as _db:
            from database import StrategicZone as _SZ
            sz_count = _db.query(_SZ).count()
        if sz_count == 0:
            print("[auto-ingest] StrategicZones: seeding baseline…")
            from seed_strategic_zones import seed_strategic_zones as _seed_sz
            stats = _seed_sz()
            print(f"[auto-ingest] StrategicZones: {stats}")
        else:
            print(f"[auto-ingest] StrategicZones: {sz_count} present, ok")
    except Exception as _e:
        print(f"[auto-ingest] StrategicZones seed failed: {_e}")

    # 10. GeoConfirmed placemarks (real per-theatre fetch, bounded to a
    # recent window — see geoconfirmed.py's upsert_theatre_placemarks
    # docstring for why the full historical archive is never bulk-imported
    # here). Runs once if the table is empty; the periodic
    # _geoconfirmed_sync_loop (registered at startup) keeps it current
    # afterward.
    try:
        with _SL() as _db:
            from database import GeoConfirmedPlacemark as _GCP
            gc_count = _db.query(_GCP).count()
        if gc_count == 0:
            print("[auto-ingest] GeoConfirmed: first sync…")
            import geoconfirmed as _gc
            stats = _gc.run_ingest()
            total_inserted = sum(p.get("inserted", 0) for p in stats.get("placemarks", []))
            print(f"[auto-ingest] GeoConfirmed: {total_inserted} placemarks inserted across "
                  f"{len(stats.get('theatres', []))} theatres; linking={stats.get('linking')}")
        else:
            print(f"[auto-ingest] GeoConfirmed: {gc_count} placemarks present, skipping first sync")
    except Exception as _e:
        print(f"[auto-ingest] GeoConfirmed first sync failed: {_e}")

    print("[auto-ingest] ✓ complete")


