@app.patch("/api/reports/{report_id}")
async def update_report(report_id: str, request: Request):
    """Only draft reports can be edited — once submitted for review, the
    content that the council actually reviewed shouldn't silently change
    out from under those findings."""
    body = await request.json()
    from database import Report, get_db as _gdb_rptupd
    with _gdb_rptupd() as db:
        row = db.query(Report).filter(Report.report_id == report_id).first()
        if not row:
            raise HTTPException(404, "Report not found")
        if row.status != "draft":
            raise HTTPException(409, f"only draft reports can be edited (this one is {row.status})")
        if "title" in body:
            if not (body["title"] or "").strip():
                raise HTTPException(400, "title cannot be blank")
            row.title = body["title"].strip()
        if "classification" in body:
            row.classification = body["classification"]
        if "key_judgments" in body:
            row.key_judgments = body["key_judgments"]
        if "claims" in body:
            row.claims_json = _json.dumps(_validate_claims(body["claims"]))
        if "narrative" in body:
            row.narrative_json = _json.dumps(body["narrative"]) if body["narrative"] is not None else None
        row.updated_at = datetime.utcnow()
        db.commit()
        return _report_to_dict(row)


@app.post("/api/reports/{report_id}/submit-for-review")
def submit_report_for_review(report_id: str):
    from database import Report, ReportSnapshot, get_db as _gdb_rptsub
    import report_council as _council
    with _gdb_rptsub() as db:
        row = db.query(Report).filter(Report.report_id == report_id).first()
        if not row:
            raise HTTPException(404, "Report not found")
        if row.status != "draft":
            raise HTTPException(409, f"only draft reports can be submitted for review (this one is {row.status})")
        claims = _json.loads(row.claims_json or "[]")
        if not claims:
            raise HTTPException(400, "cannot submit a report with no claims")
        snap = db.query(ReportSnapshot).filter(ReportSnapshot.snapshot_id == row.snapshot_id).first()
        if not snap:
            raise HTTPException(500, f"report's snapshot {row.snapshot_id} no longer exists")
        snapshot_content = _json.loads(snap.content_json)

        # Real bypass, only for a genuine run_council() exception — never
        # for its normal, honest "skipped" lens status (no API key), which
        # is an expected outcome run_council() already returns cleanly and
        # is untouched here. A report must never get stuck in draft/
        # in_review limbo because of a real bug/timeout/outage in the
        # council call itself; it advances to in_review either way, but a
        # bypass carries a real, visible flag + the real error (never a
        # vague or fabricated message) so a reviewer sees plainly that
        # automated review did not actually run before approving.
        try:
            findings = _council.run_council(
                report_title=row.title, key_judgments=row.key_judgments, claims=claims,
                snapshot_content=snapshot_content, client=llm_gate.get_client(llm_gate.COUNCIL, _api_key),
                usage_tracker_mod=usage_tracker, db=db,
            )
        except Exception as council_exc:
            logger.exception(f"[submit_for_review] run_council() raised for {report_id} — bypassing council, report still advances to in_review")
            bypass_reason = f"council_bypassed: {type(council_exc).__name__}: {council_exc}"
            findings = {
                "deterministic": [],
                "citation_fidelity": {"status": "error", "reason": bypass_reason, "findings": []},
                "completeness": {"status": "error", "reason": bypass_reason, "findings": []},
                "council_bypassed": True,
                "council_bypass_error": {"type": type(council_exc).__name__, "message": str(council_exc)},
            }
        row.council_findings_json = _json.dumps(findings, default=str)
        row.council_run_at = datetime.utcnow()
        row.status = "in_review"
        row.updated_at = datetime.utcnow()
        db.commit()
        return _report_to_dict(row)


