@app.get("/api/fusions")
def api_fusions_list(
    status: str = "active",
    severity: str = None,
    since: str = None,
    limit: int = 100,
):
    try:
        from database import get_db as _gdb_f, FusionEvent as _FE
        import json as _json
    except ImportError:
        raise HTTPException(status_code=503, detail="Fusion engine not available")
    with _gdb_f() as _db:
        q = _db.query(_FE)
        if status and status != "all":
            q = q.filter(_FE.status == status)
        if severity:
            q = q.filter(_FE.severity == severity)
        if since:
            try:
                _since_dt = datetime.fromisoformat(since)
                q = q.filter(_FE.created_at >= _since_dt)
            except ValueError:
                pass
        # Exclude synthetic rows written by test_gdelt_fusion_signal.py's own
        # (intentional, documented) practice of writing real FusionEvent rows into
        # this same production DB. That test tags every row it creates with
        # "AUTOMATED TEST" in location_name and a "TEST-"-prefixed fusion_id/signal_id
        # — filter those out permanently, not as a one-time cleanup, since the test
        # keeps running and keeps writing new rows. (Guard against NULL location_name/
        # fusion_id with OR ... IS NULL — a bare NOT LIKE silently drops NULL rows in SQL.)
        from sqlalchemy import or_ as _or_fus
        q = q.filter(_or_fus(_FE.location_name.is_(None), ~_FE.location_name.like("%AUTOMATED TEST%")))
        q = q.filter(_or_fus(_FE.fusion_id.is_(None), ~_FE.fusion_id.like("TEST-%")))
        rows = q.order_by(_FE.created_at.desc()).limit(limit).all()
        result = []
        for r in rows:
            result.append({
                "fusion_id": r.fusion_id,
                "title": r.title,
                "subtitle": r.subtitle,
                "narrative": r.narrative,
                "severity": r.severity,
                "confidence": r.confidence,
                "correlation_strength": r.correlation_strength,
                "correlation_components": _json.loads(r.correlation_components) if r.correlation_components else None,
                "domain_count": r.domain_count,
                "domains": _json.loads(r.domains or "[]"),
                "fusion_type": r.fusion_type,
                "location_name": r.location_name,
                "location_country": r.location_country,
                "region_id": r.region_id,
                "lat": r.lat,
                "lon": r.lon,
                "radius_km": r.radius_km,
                "signal_count": r.signal_count,
                "key_signals": _json.loads(r.key_signals or "[]"),
                "threat_indicators": _json.loads(r.threat_indicators or "[]"),
                "recommended_actions": _json.loads(r.recommended_actions or "[]"),
                "contributing_assessments": _json.loads(r.contributing_assessments or "[]"),
                "contributing_alert_ids": _json.loads(r.contributing_alert_ids or "[]"),
                "contributing_rule_ids": _json.loads(r.contributing_rule_ids or "[]"),
                "marker_type": r.marker_type,
                "marker_visible": r.marker_visible,
                "status": r.status,
                "created_at": r.created_at.isoformat() if r.created_at else None,
                "updated_at": r.updated_at.isoformat() if r.updated_at else None,
                "expires_at": r.expires_at.isoformat() if r.expires_at else None,
                "analyst_notes": r.analyst_notes,
            })
        return result


