# Real presence — Option A chosen explicitly (see this round's own report):
# no real live-update channel exists anywhere in this app that could push
# presence to the browser (the AIS "WebSocket" is a backend-to-vendor
# ingest client, never exposed to the frontend; every real "live" feature
# here is REST polling, confirmed by audit). Rather than a purely
# decorative color/initial derived only from the record ref (no real
# "who has this open" tracking existed anywhere to derive it FROM, so a
# pure function of the ref alone would carry zero real information), this
# is the minimal REAL tracking actually built for this: a genuine
# server-side heartbeat the client posts every ~15s while a record panel
# is open, read back via a real GET. Not push-based — a viewer's presence
# can lag up to one heartbeat interval — so the UI must say "viewing now"
# or similar, never "live".
_PRESENCE: dict = {}
_PRESENCE_LOCK = threading.Lock()
_PRESENCE_TTL_SECONDS = 45

@app.post("/api/presence")
def api_presence_heartbeat(record_ref: str, request: Request):
    current_user = _require_current_user(request)
    with _PRESENCE_LOCK:
        _PRESENCE.setdefault(record_ref, {})[current_user["id"]] = time.time()
    return {"ok": True}

@app.get("/api/presence")
def api_presence_get(record_ref: str):
    now = time.time()
    with _PRESENCE_LOCK:
        seen = dict(_PRESENCE.get(record_ref, {}))
    active_ids = [uid for uid, ts in seen.items() if now - ts <= _PRESENCE_TTL_SECONDS]
    from database import User, get_db as _gdb_presence
    with _gdb_presence() as db:
        users = db.query(User).filter(User.id.in_(active_ids)).all() if active_ids else []
        return {"users": [_user_to_dict(u) for u in users], "ttl_seconds": _PRESENCE_TTL_SECONDS}


@app.patch("/api/forge/ontology/node/{node_id}")
async def api_forge_ontology_node_patch(node_id: str, request: Request):
    """Real edits to an existing Forge ontology node (label/risk/description/
    arbitrary key-value props) — a small, safe addition alongside the
    existing create/delete endpoints, following the same load/mutate/save
    pattern."""
    body = await request.json()
    ontology = _forge_ontology_load()
    node = next((n for n in ontology["nodes"] if n.get("id") == node_id), None)
    if not node:
        raise HTTPException(404, f"ontology node {node_id} not found")
    if "label" in body:
        node["label"] = body["label"]
    if "description" in body:
        node["description"] = body["description"]
    if "props" in body and isinstance(body["props"], dict):
        node["description"] = "; ".join(f"{k}={v}" for k, v in body["props"].items() if k not in ("lat", "lon", "source"))
    _forge_ontology_save(ontology)
    return node


@app.patch("/api/forge/ontology/edge/{edge_id}")
async def api_forge_ontology_edge_patch(edge_id: str, request: Request):
    body = await request.json()
    ontology = _forge_ontology_load()
    edge = next((e for e in ontology["edges"] if e.get("id") == edge_id), None)
    if not edge:
        raise HTTPException(404, f"ontology edge {edge_id} not found")
    if "kind" in body:
        edge["type"] = body["kind"]
    if "note" in body:
        edge["note"] = body["note"]
    if "conf" in body:
        edge["conf"] = float(body["conf"])
    _forge_ontology_save(ontology)
    return edge


# ── Threat matrix explainability ─────────────────────────────────────────────

@app.get("/api/analytics/threat-matrix/{region_name}/explain")
def api_threat_matrix_explain(
    region_name: str,
    current_user=None,
):
    from database import (Alert as _AMex, FusionEvent as _FMex, SurgeEvent as _SMex,
                          SentinelDetection as _SDex, OntologyLink as _OLex,
                          get_db as _gdb_ex)
    import json as _jex
    from threat_matrix import REGIONS, _in_bbox, _threat_level
    region_name_decoded = region_name.replace("+", " ")
    region = REGIONS.get(region_name_decoded)
    if not region:
        raise HTTPException(status_code=404, detail=f"Region '{region_name_decoded}' not found")

    bbox   = region["bbox"]
    now    = datetime.utcnow()
    cutoff = now - timedelta(hours=24)

    with _gdb_ex() as _db:
        # Collect driver data
        db_alerts = (_db.query(_AMex)
                     .filter(_AMex.status == "active", _AMex.created_at >= cutoff,
                             _AMex.lat.between(bbox["min_lat"], bbox["max_lat"]),
                             _AMex.lon.between(bbox["min_lon"], bbox["max_lon"]))
                     .order_by(_AMex.created_at.desc()).limit(20).all())

        fusions = (_db.query(_FMex)
                   .filter(_FMex.status == "active", _FMex.expires_at > now,
                           _FMex.lat.isnot(None))
                   .all())
        fusions_in = [f for f in fusions if _in_bbox(f.lat, f.lon, bbox)]

        surges = (_db.query(_SMex)
                  .filter(_SMex.status == "active", _SMex.expires_at > now)
                  .all())
        surges_in = [s for s in surges
                     if _in_bbox(s.lat, s.lon, bbox) if s.lat]

        sentinels = (_db.query(_SDex)
                     .filter(_SDex.created_at >= cutoff)
                     .all())
        sents_in = [d for d in sentinels if _in_bbox(d.centroid_lat, d.centroid_lon, bbox)]

        links_in = (_db.query(_OLex)
                    .filter(_OLex.created_at >= cutoff)
                    .limit(50).all())

        # Score breakdown
        SEV_W = {"info": 0.5, "medium": 1, "high": 2, "critical": 4}
        weighted = sum(SEV_W.get(a.severity or "medium", 1) for a in db_alerts)
        forge_n  = len([a for a in db_alerts if a.source in ("ais","adsb","sentinel")])
        sent_sc  = sum(SEV_W.get(d.severity or "info", 1) for d in sents_in)
        fus_sc   = len(fusions_in) * 15
        surge_sc = sum(10 for _ in surges_in)
        link_sc  = min(len(links_in), 10)
        base_sc  = min(weighted * 2, 40)
        forge_sc = min(forge_n * 5, 25)
        total    = min(base_sc + forge_sc + min(sent_sc, 20) + min(fus_sc, 30)
                       + min(surge_sc, 25) + link_sc, 100.0)

        drivers = {
            "alerts":    [{"alert_id": a.alert_id, "title": a.title,
                           "severity": a.severity, "source": a.source,
                           "lat": a.lat, "lon": a.lon} for a in db_alerts[:5]],
            "fusions":   [{"fusion_id": f.fusion_id, "title": f.title,
                           "severity": f.severity, "confidence": f.confidence}
                          for f in fusions_in[:5]],
            "surges":    [{"surge_id": s.surge_id, "headline": s.headline,
                           "severity": s.severity} for s in surges_in[:3]],
            "sentinels": [{"detection_id": d.detection_id, "object_type": d.object_type,
                           "severity": d.severity, "confidence": d.confidence,
                           "nearest_port": d.nearest_port} for d in sents_in[:3]],
            "links":     [{"link_id": l.link_id, "source_type": l.source_type,
                           "entity_type": l.entity_type, "entity_name": l.entity_name}
                          for l in links_in[:5]],
        }

    # Generate Haiku explanation
    explanation = ""
    if client:
        try:
            driver_txt = (
                f"Region: {region_name_decoded}\n"
                f"Alert count: {len(db_alerts)} (forge: {forge_n})\n"
                f"Fusion events: {len(fusions_in)}\n"
                f"Surge events: {len(surges_in)}\n"
                f"Sentinel detections: {len(sents_in)}\n"
                f"Top alerts: {'; '.join(a['title'] for a in drivers['alerts'][:3])}\n"
                f"Top fusions: {'; '.join(f['title'] for f in drivers['fusions'][:2])}\n"
            )
            _msg = client.messages.create(
                model="claude-haiku-4-5-20251001",
                max_tokens=200, temperature=0,
                system="You are an intelligence analyst. Write one precise paragraph explaining why this region has an elevated threat score. Analyst voice, specific, no preamble.",
                messages=[{"role": "user", "content": driver_txt}],
            )
            explanation = _msg.content[0].text.strip()
        except Exception as _hex:
            explanation = f"Score driven by {len(db_alerts)} active alerts and {len(fusions_in)} fusion events in {region_name_decoded}."

    return {
        "region":      region_name_decoded,
        "score":       round(total, 1),
        "threat_level": _threat_level(total),
        "explanation": explanation,
        "drivers":     drivers,
        "score_breakdown": {
            "base_alert_score": round(base_sc, 1),
            "forge_bonus":      round(forge_sc, 1),
            "fusion_score":     round(min(fus_sc, 30), 1),
            "surge_bonus":      round(min(surge_sc, 25), 1),
            "sentinel_score":   round(min(sent_sc, 20), 1),
            "link_bonus":       link_sc,
            "total":            round(total, 1),
        },
    }


@app.get("/api/analytics/threat-matrix")
def analytics_threat_matrix():
    """Current threat scores for all regions — from hourly in-memory cache."""
    cached = threat_matrix.get_cached_scores()
    if cached:
        return cached
    # Cache cold (first startup) — compute live
    active_events = []
    try:
        active_events = es.get_active_events()
    except Exception as e:
        logger.exception("threat_matrix: event store query failed")
        pass
    _fusions_live = []
    try:
        if _fusion_engine:
            from database import FusionEvent as _FE_live, get_db as _gdb_fev
            with _gdb_fev() as _dbfev:
                _fusions_live = [
                    {"lat": r.lat, "lon": r.lon, "severity": r.severity}
                    for r in _dbfev.query(_FE_live).filter(
                        _FE_live.status == "active", _FE_live.marker_visible == True
                    ).all()
                ]
    except Exception as e:
        logger.exception("threat_matrix: fusion query failed")
        pass
    from database import get_db as _gdb_tm2
    with _gdb_tm2() as _db:
        return threat_matrix.refresh_cache(_db, list(_forge_alerts), active_events, _fusions_live)


@app.get("/api/analytics/threat-matrix/history")
def analytics_threat_matrix_history(
    region_name: str = Query(None),
    days: int = Query(30, ge=1, le=365),
):
    """Historical threat snapshots for a region (or all regions)."""
    from database import ThreatMatrixSnapshot, get_db as _gdb_tm3
    import json as _j
    cutoff = (datetime.utcnow() - timedelta(days=days)).strftime("%Y-%m-%d")
    with _gdb_tm3() as _db:
        q = _db.query(ThreatMatrixSnapshot).filter(ThreatMatrixSnapshot.snapshot_date >= cutoff)
        if region_name:
            q = q.filter(ThreatMatrixSnapshot.region_name == region_name)
        rows = q.order_by(ThreatMatrixSnapshot.snapshot_date).all()
        return [
            {
                "snapshot_date":             r.snapshot_date,
                "region_name":               r.region_name,
                "region_id":                 r.region_id,
                "threat_score":              r.threat_score,
                "threat_level":              r.threat_level,
                "alert_count":               r.alert_count,
                "forge_alert_count":         r.forge_alert_count,
                "sentinel_detection_count":  r.sentinel_detection_count,
                "news_event_count":          r.news_event_count,
                "contributing_signals":      _j.loads(r.contributing_signals or "[]"),
            }
            for r in rows
        ]


# ── Ontology ──────────────────────────────────────────────────────────────────

def _forge_ontology_load():
    path = _FORGE_DIR / "forge_ontology.json"
    if not path.exists():
        return {"nodes": [], "edges": []}
    try:
        return _json.loads(path.read_text())
    except Exception:
        return {"nodes": [], "edges": []}


def _forge_ontology_integrity_check(ontology: dict) -> list[dict]:
    """Every node persisted into forge_ontology.json should be traceable to a
    real source: an uploaded-document citation (`source: "upload"`, set by
    _add_entities_to_ontology), a live subsystem snapshot (`source:
    "live:<type>"`, set by forge_build_ontology's add_node() and by
    _auto_add_correlation_to_ontology), or an explicit operator entry
    (`manual: True`, set by POST /api/forge/ontology/node). A node with none
    of these — and that isn't even the endpoint of an edge carrying a real
    `claim_id` (the human-approved-claims path) — has no traceable origin at
    all. That is exactly the shape of the old bug this safeguard exists for:
    forge_build_ontology() used to inject ~45 hardcoded country/group/person
    nodes as frozen Python literals with zero sourcing, indistinguishable
    from genuinely-computed graph output, and because this file is only ever
    merge-added-to (see forge_build_ontology's dedup-by-label logic — nothing
    here ever purges), those nodes would have sat in this file forever even
    after the generating code was fixed.
    This check never deletes or mutates anything — deletion should be a
    deliberate human decision, not something a safeguard does silently. It
    only flags, so a future regression (a new code path that writes a node
    with no real source) shows up immediately in the logs instead of quietly
    accumulating for months like the original bug did.
    """
    nodes = ontology.get("nodes", [])
    edges = ontology.get("edges", [])
    claim_backed_ids = {e.get("source") for e in edges if e.get("claim_id")}
    claim_backed_ids |= {e.get("target") for e in edges if e.get("claim_id")}
    flagged = []
    for n in nodes:
        if n.get("source") or n.get("manual") or n.get("id") in claim_backed_ids:
            continue
        flagged.append({"id": n.get("id"), "type": n.get("type"), "label": n.get("label")})
    return flagged


def _forge_ontology_save(ontology: dict):
    _FORGE_DIR.mkdir(parents=True, exist_ok=True)
    flagged = _forge_ontology_integrity_check(ontology)
    if flagged:
        sample = "; ".join(f"{f.get('type')}:{f.get('label')}" for f in flagged[:10])
        logger.warning(
            "[ontology-integrity] %d node(s) with no traceable source (no "
            "'source'/'manual' tag, not backed by a claim_id edge) — "
            "flagged, NOT auto-removed. Sample: %s",
            len(flagged), sample,
        )
    _atomic_write_text(
        _FORGE_DIR / "forge_ontology.json",
        _json.dumps(ontology, indent=2, ensure_ascii=False),
    )


